const o={"philo-art":[["L’art","Activité de création d’œuvres visant une valeur esthétique, non l’utilité."],["Art / artisanat","L’artisan reproduit un objet utile ; l’artiste crée une œuvre singulière."],["Beau / agréable","Le beau prétend valoir pour tous ; l’agréable plaît seulement à mes sens."],["Esthétique","Réflexion sur le beau et sur l’art."],["Jugement de goût","Chez Kant : jugement subjectif (« c’est beau ») qui prétend pourtant à l’universel."],["Mimésis (imitation)","Idée que l’art imite le réel ; critiquée par Platon comme illusion."]],"philo-justice":[["La justice","Ce qui est conforme au droit et à l’équité ; distinguer légal et légitime."],["Légal / légitime","Conforme à la loi (légal) / conforme à la justice (légitime)."],["Équité","Correction de la loi générale quand elle est injuste dans un cas particulier."],["Égalité arithmétique / proportionnelle","La même chose pour tous / à chacun selon son mérite ou son besoin (Aristote)."],["Désobéissance civile","Enfreindre publiquement une loi jugée injuste au nom d’une justice supérieure."],["Droit","Ensemble des règles qui organisent la vie en société."]],"philo-liberte":[["La liberté","Pouvoir d’agir selon sa volonté ; s’oppose au déterminisme et suppose la responsabilité."],["Autonomie / licence","Se donner sa propre loi (Kant) / faire n’importe quoi."],["Déterminisme","Thèse selon laquelle tout événement a une cause ; interroge la liberté."],["Libre arbitre","Pouvoir de choisir sans y être contraint."],["Responsabilité","Devoir de répondre de ses actes, qui suppose la liberté."],["Aliénation","État où l’on est dépossédé de sa liberté (par une dépendance, un pouvoir…)."]],"philo-nature":[["La nature","Ce qui n’est pas produit par l’homme ; aussi l’essence d’une chose, ou l’inné."],["Nature / culture","Ce qui est donné / ce que l’homme produit et transmet (langage, techniques)."],["Inné / acquis","De naissance / obtenu par l’expérience et l’éducation."],["Sophisme naturaliste","Erreur qui confond le fait (naturel) et la valeur (bien)."],["Principe responsabilité","Devoir (Jonas) de préserver la nature et les générations futures."],["Écologie","Réflexion et action sur le rapport de l’homme à son environnement."]],"philo-religion":[["La religion","Ensemble de croyances et de pratiques reliant l’homme au sacré."],["Croire / savoir","Adhérer sans preuve (croire) / tenir pour vrai avec preuve (savoir)."],["Foi","Adhésion du croyant, qui ne repose pas sur la démonstration."],["Sacré","Ce qui est mis à part, objet de respect religieux (≠ profane)."],["Illusion (Freud)","Croyance née d’un désir, non d’une preuve."],["Lien social (Durkheim)","Fonction de la religion qui soude et unit le groupe."]],"philo-technique":[["La technique","Ensemble des procédés efficaces produits par l’homme pour transformer la nature."],["Moyen / fin","La technique est un moyen ; tout dépend de la fin (l’usage) qu’on en fait."],["Homo faber","L’homme défini comme fabricant d’outils (Bergson)."],["Travail","Activité par laquelle l’homme transforme la nature et se transforme lui-même."],["Aliénation par la technique","Dépendance ou dépossession créée par les machines et les procédés."],["Progrès","Amélioration ; à ne pas confondre : progrès technique ≠ progrès moral."]],"philo-verite":[["La vérité","Accord de la pensée avec son objet ; s’oppose à l’erreur et à l’illusion."],["Vérité / réalité","La réalité est ce qui est ; la vérité qualifie nos jugements sur le réel."],["Opinion (doxa)","Croyance non fondée, à distinguer du savoir justifié."],["Doute méthodique","Chez Descartes : douter volontairement de tout pour atteindre une certitude."],["Cogito","« Je pense, donc je suis » : la première certitude cartésienne."],["Démontrer / prouver","Établir par la logique / établir par l’expérience (Leibniz : raison / fait)."]],"philo-methode":[["Problématique","Question précise, née d’une tension, qui structure toute la réflexion."],["Thèse","Réponse défendue à la question posée."],["Argument","Raison qui justifie une thèse."],["Concept","Idée générale et abstraite définie avec précision."],["Dissertation","Démonstration organisée qui répond à un sujet par étapes argumentées."],["Explication de texte","Analyse ordonnée qui dégage la thèse, les arguments et les enjeux d’un texte."],["Dialectique","Progression par étapes : thèse, antithèse, dépassement."],["Dépassement (synthèse)","Troisième moment qui résout la tension entre thèse et antithèse."]]},d=Object.freeze(Object.defineProperty({__proto__:null,default:o},Symbol.toStringTag,{value:"Module"})),l={"philo-art":{sections:[{h:"🏛️ Aux sources — une histoire de l’idée d’art",blocks:[{t:"p",c:"Le mot « art » vient du latin *ars*, qui traduit le grec *tekhnê* : à l’origine, il ne désigne pas du tout ce que nous appelons aujourd’hui l’art, mais tout **savoir-faire**, toute compétence réglée — celle du menuisier comme celle du médecin ou du navigateur. Pendant des siècles, le peintre et le sculpteur furent considérés comme des **artisans**, membres de corporations, exécutant des commandes. L’idée moderne d’un « artiste » singulier, créateur inspiré et libre, est une invention récente, née à la **Renaissance** et pleinement affirmée au **XIXᵉ siècle** avec le romantisme."},{t:"p",c:"Dès l’Antiquité, deux grandes conceptions s’affrontent. Pour **Platon**, l’art est **imitation** (*mimésis*) : le peintre copie un lit particulier, qui n’est lui-même que la copie de l’Idée de lit ; l’œuvre est donc une « copie de copie », deux fois éloignée de la vérité, et le poète, qui flatte les passions, est même banni de la cité idéale de *La République*. Pour **Aristote**, au contraire, l’imitation est naturelle et instructive : la tragédie, en représentant des actions terribles, produit une **catharsis**, une purgation des émotions qui élève l’âme. Ces deux positions — l’art qui trompe / l’art qui forme — traversent toute l’histoire de la pensée."},{t:"table",head:["Époque","Ce que devient l’art","Idée directrice"],rows:[["Antiquité","Imitation (mimésis) et savoir-faire","Platon (méfiance) / Aristote (catharsis)"],["Moyen Âge","Art sacré au service de la foi","L’œuvre élève l’âme vers Dieu"],["Renaissance","Perspective, anatomie, « génie »","L’artiste égale le savant (Vinci)"],["XVIIIᵉ s.","Naissance de l’esthétique","Kant : le jugement de goût"],["XIXᵉ s.","L’art pour l’art, le génie romantique","Hugo, Baudelaire, Hegel"],["XXᵉ s.","Ruptures : abstraction, ready-made","Duchamp, Kandinsky, l’art conceptuel"]]},{t:"p",c:"Au **XVIIIᵉ siècle**, l’**esthétique** devient une discipline (Baumgarten forge le mot), et **Kant** en pose les fondements : le beau n’est ni l’agréable (qui flatte les sens) ni le bon (qui satisfait la raison morale) ; il procure un « plaisir désintéressé » et, chose remarquable, prétend valoir **pour tout le monde** sans reposer sur un concept. **Hegel**, lui, voit dans l’art l’une des voies par lesquelles l’**Esprit** prend conscience de lui-même : l’œuvre n’imite pas, elle **manifeste** une vérité sensible sur l’humanité. Puis le XXᵉ siècle fait exploser toutes les certitudes : avec la *Fontaine* de **Duchamp** (1917), ce n’est plus l’objet ni le métier qui font l’œuvre, mais le **geste** de l’artiste et l’**institution** qui l’expose."},{t:"tip",h:"À retenir",c:"L’idée d’« art » a une **histoire** : opposer « avant on savait faire, aujourd’hui n’importe quoi est de l’art » est un cliché ; la vraie question est de savoir **ce qui fait la valeur** d’une œuvre à chaque époque."}]},{h:"📖 L’art dans la littérature et les arts",blocks:[{t:"p",c:"La littérature n’a cessé d’interroger le pouvoir — et le danger — de l’art. Dans *Le Portrait de Dorian Gray* d’**Oscar Wilde**, un tableau vieillit et se corrompt à la place de son modèle resté jeune : l’œuvre devient le miroir de l’âme, et pose la question du rapport entre **beauté** et **morale**. Chez **Balzac**, *Le Chef-d’œuvre inconnu* met en scène un peintre qui, à force de recherche de la perfection, ne produit plus qu’un chaos de couleurs : l’art peut se perdre dans sa propre exigence."},{t:"p",c:"Chez **Marcel Proust**, dans *À la recherche du temps perdu*, l’art n’est pas un ornement mais un **salut** : seule l’œuvre (la petite phrase de Vinteuil, les toiles d’Elstir) permet de retrouver le temps perdu et de donner un sens à l’existence. **Baudelaire**, dans *Les Fleurs du mal*, revendique de « faire de la boue et d’en tirer de l’or » : l’art transfigure le laid et arrache une beauté au réel le plus sordide. À l’inverse, **Platon** aurait vu là un danger — celui d’aimer les apparences plutôt que la vérité."},{t:"example",h:"Illustration",c:"**Guernica** de Picasso (1937) ne « représente » pas joliment le bombardement d’une ville : par sa déformation, son noir et blanc, ses cris figés, il rend **visible** l’horreur de la guerre mieux qu’une photographie. C’est l’idée de Klee : « L’art ne reproduit pas le visible, il rend visible. »"},{t:"tip",h:"Réflexe de dissertation",c:"Un exemple **littéraire ou artistique précis**, expliqué (pas seulement cité), vaut mieux que dix généralités. Montre **ce que l’œuvre fait**, pas seulement qu’elle existe."}]},{h:"✍️ Dissertation guidée — « N’y a-t-il de beau que l’utile ? »",blocks:[{t:"p",c:"**Introduction.** On dit souvent d’un objet bien conçu qu’il est « beau parce qu’il est pratique » : une voiture, un outil, un pont. Cela laisserait entendre que la beauté se ramène à l’**utilité**. Pourtant, une fleur inutile, un coucher de soleil, une symphonie nous paraissent beaux sans servir à rien. Le beau se confond-il avec l’utile, ou faut-il, au contraire, qu’une chose soit **inutile** — désintéressée — pour être vraiment belle ?"},{t:"list",c:["**I. Le beau semble lié à l’utile.** Ce qui est bien adapté à sa fonction nous plaît (un objet « fonctionnel ») ; l’architecture, le design, l’artisanat unissent forme et usage. Argument : la beauté serait la perfection visible d’une fonction.","**II. Mais le beau est désintéressé.** Pour **Kant**, le jugement de goût est **sans intérêt** : je ne demande pas à quoi sert une rose pour la trouver belle. L’œuvre d’art ne se réduit jamais à un usage ; un tableau qui ne servirait qu’à « décorer » cesserait d’être une œuvre.","**III. Dépassement.** Le beau et l’utile ne s’opposent pas terme à terme : une chose peut être belle *et* utile, mais sa beauté ne **vient pas** de son utilité. Le beau ouvre un rapport au monde plus libre — il nous arrache, un instant, à la logique des moyens et des fins."]},{t:"example",h:"Conclusion rédigée",c:"L’utile peut être beau, mais la beauté ne se laisse jamais **enfermer** dans l’utilité : elle commence précisément là où cesse le calcul des fins. C’est pourquoi l’art, souverainement inutile, est peut-être ce dont l’homme a le plus besoin."}]}],resources:[{label:"France Culture — l’art et l’esthétique",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Émissions sur le beau, la création, Kant, Hegel."}]},"philo-justice":{sections:[{h:"🏛️ Aux sources — justice, loi et cité",blocks:[{t:"p",c:"La question de la justice naît avec la **cité** grecque. Dans *La République*, **Platon** fait dire au sophiste **Thrasymaque** que « la justice n’est que l’intérêt du plus fort » : les lois seraient toujours faites par les puissants pour les puissants. Toute la philosophie politique va s’efforcer de réfuter ce **cynisme** — de montrer que le juste ne se réduit pas au rapport de force. Pour Platon, la justice est l’**harmonie** de l’âme et de la cité, où chacun est à sa place ; pour **Aristote**, elle est une **vertu** et se dit de deux façons."},{t:"table",head:["Forme de justice (Aristote)","Principe","Exemple"],rows:[["Justice distributive","À chacun selon son mérite (égalité proportionnelle)","Répartir des récompenses selon le travail fourni"],["Justice corrective / commutative","Rétablir l’égalité rompue","Réparer un tort, punir un vol"],["Équité (epieikeia)","Corriger la loi générale dans le cas particulier","Adoucir une peine injuste au regard des circonstances"]]},{t:"p",c:"À l’époque moderne, la justice se pense à partir du **contrat**. **Hobbes** part d’un « état de nature » où règne la « guerre de tous contre tous » : les hommes, par peur de la mort, cèdent leur droit à un souverain qui garantit la paix. **Rousseau** refuse cette soumission : le pacte social légitime n’aliène pas la liberté, il la fonde, car obéir à la loi qu’on s’est prescrite, c’est être libre. Au XXᵉ siècle, **John Rawls** propose une expérience de pensée célèbre : sous un « **voile d’ignorance** » (ne sachant pas quelle place on occupera dans la société), quelles règles choisirait-on ? Celles qui protègent le plus **les plus défavorisés**."},{t:"tip",h:"Distinction essentielle",c:"**Légal** (conforme à la loi) ≠ **légitime** (conforme à la justice). Tout le débat politique tient dans cet écart : une loi peut être légale sans être juste."}]},{h:"📖 La justice en littérature — de l’injustice à la révolte",blocks:[{t:"p",c:"La littérature donne un visage à l’injustice. Dans *Les Misérables* de **Victor Hugo**, Jean Valjean est condamné au bagne pour un pain volé : le roman dénonce une justice **légale** qui écrase les misérables au lieu de les relever, et oppose la loi implacable de Javert à la **miséricorde** de l’évêque. Chez **Kafka**, *Le Procès* montre un homme arrêté et jugé sans jamais connaître le motif de son accusation : c’est le cauchemar d’une justice devenue **absurde**, machine anonyme qui broie l’individu."},{t:"p",c:"**Antigone**, de Sophocle, met en scène le conflit le plus pur : Antigone enterre son frère au mépris de l’interdit du roi Créon, opposant les **lois non écrites** (divines, morales) aux **lois de la cité**. Doit-on obéir à une loi que l’on juge injuste ? La **désobéissance civile** — de Thoreau à Gandhi, de Rosa Parks à Martin Luther King — répond que oui, à condition d’agir publiquement, pacifiquement, et d’accepter la sanction, au nom d’une justice supérieure."},{t:"example",h:"Illustration",c:"Dans *L’Étranger* de **Camus**, Meursault est condamné moins pour son meurtre que pour n’avoir pas pleuré à l’enterrement de sa mère : la justice juge alors une **conformité sociale**, non un acte. Le roman interroge : que juge-t-on vraiment dans un tribunal ?"},{t:"warning",h:"Piège",c:"Ne pas confondre **la justice** (idéal moral et politique) avec **l’appareil judiciaire** (les tribunaux). On peut trouver une décision de justice… injuste."}]},{h:"✍️ Dissertation guidée — « Est-il toujours juste d’obéir à la loi ? »",blocks:[{t:"list",c:["**I. La loi est la condition de la justice.** Sans loi commune, c’est la loi du plus fort (Hobbes) ; la loi, égale pour tous, protège le faible et rend la vie sociale possible. Désobéir, ce serait ouvrir la porte à l’arbitraire de chacun.","**II. Mais une loi peut être injuste.** L’histoire le prouve (lois ségrégationnistes, lois d’exception) : le légal n’est pas toujours le légitime. Obéir aveuglément peut rendre complice (procès de Nuremberg, Arendt et la « banalité du mal »).","**III. Dépassement : la désobéissance civile.** Enfreindre **publiquement** une loi injuste, au nom d’une justice supérieure et en acceptant la sanction, n’est pas de l’anarchie : c’est encore respecter l’idée de loi, en appelant à une loi meilleure."]},{t:"example",h:"Ouverture",c:"La vraie obéissance n’est pas la soumission : c’est l’adhésion réfléchie à des lois que l’on peut, en conscience, reconnaître comme justes — et, quand elles ne le sont pas, le courage de les contester dans les formes du droit."}]}],resources:[{label:"France Culture — justice, droit, politique",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Rawls, Rousseau, la désobéissance civile."}]},"philo-liberte":{sections:[{h:"🏛️ Aux sources — sommes-nous libres ?",blocks:[{t:"p",c:"La liberté est peut-être la notion la plus intime et la plus disputée. Le sens commun l’identifie au **libre arbitre** : le pouvoir de choisir sans y être contraint. Mais dès l’Antiquité, les **stoïciens** distinguent ce qui **dépend de nous** (nos jugements, nos désirs) de ce qui **n’en dépend pas** (les événements, la mort, l’opinion d’autrui) : être libre, pour Épictète, ce n’est pas tout pouvoir, c’est ne désirer que ce qui dépend de nous. La liberté devient alors une **conquête intérieure**, non une absence de contraintes."},{t:"p",c:"L’âge classique oppose deux camps. Pour **Descartes**, la liberté est une évidence : le libre arbitre est « la principale perfection de l’homme », si grand qu’il nous rend « en quelque façon semblables à Dieu ». Pour **Spinoza**, au contraire, cette liberté est une **illusion** : nous nous croyons libres parce que nous avons conscience de nos actions, mais nous **ignorons les causes** qui nous déterminent — telle la pierre lancée qui, si elle pensait, se croirait libre de tomber. Le **déterminisme** (tout a une cause) semble ainsi menacer la liberté."},{t:"table",head:["Penseur","Thèse sur la liberté","Formule"],rows:[["Épictète","Liberté = maîtrise de ce qui dépend de nous","« Ce qui dépend de nous… »"],["Descartes","Le libre arbitre est une évidence","« La principale perfection de l’homme »"],["Spinoza","La liberté est une illusion (déterminisme)","La pierre qui se croit libre"],["Kant","Liberté = autonomie (se donner sa loi)","Agir par devoir, non par penchant"],["Sartre","L’homme est condamné à être libre","« L’existence précède l’essence »"]]},{t:"p",c:"**Kant** dépasse le conflit : la liberté n’est pas dans le monde des phénomènes (où tout est déterminé), mais dans le domaine **moral**. Être libre, c’est être **autonome** : se donner à soi-même sa propre loi, agir par **devoir** et non par simple penchant. **Sartre**, enfin, radicalise : il n’y a pas de « nature humaine » qui nous excuserait ; « l’existence précède l’essence », nous sommes ce que nous **faisons** de nous, et donc **responsables** — d’où l’angoisse d’une liberté sans mode d’emploi."},{t:"tip",h:"Distinction clé",c:"**Liberté ≠ licence.** Faire tout ce qui passe par la tête, c’est être l’esclave de ses désirs ; l’autonomie (se donner sa loi) est une liberté supérieure."}]},{h:"📖 La liberté en littérature et en histoire",blocks:[{t:"p",c:"La littérature explore les prisons visibles et invisibles de l’homme. *1984* de **George Orwell** décrit un État totalitaire qui contrôle jusqu’aux pensées : la liberté y survit dans le simple fait de dire « 2 + 2 = 4 ». *Le Meilleur des mondes* d’**Aldous Huxley** imagine une servitude plus insidieuse encore — une population si divertie et droguée au plaisir qu’elle **aime** sa servitude et ne réclame plus aucune liberté. Deux avertissements complémentaires : on peut asservir par la terreur, mais aussi par le divertissement."},{t:"p",c:"Chez **Sartre**, la pièce *Huis clos* (« l’enfer, c’est les autres ») et le roman *La Nausée* mettent en scène le vertige d’une liberté totale : sans Dieu ni nature pour décider à notre place, l’homme doit **s’inventer**. **Camus**, dans *Le Mythe de Sisyphe*, tire de l’absurde une liberté paradoxale : condamné à pousser éternellement son rocher, Sisyphe est libre parce qu’il **assume** son destin — « il faut imaginer Sisyphe heureux »."},{t:"example",h:"Illustration",c:"Le fumeur qui dit « je suis libre de fumer » est peut-être l’esclave de son addiction : la conscience d’un choix ne prouve pas la liberté du choix. C’est exactement l’objection de Spinoza."},{t:"tip",h:"Réflexe",c:"Relier **liberté** et **responsabilité** : si je suis libre, je réponds de mes actes ; nier ma liberté, c’est souvent chercher une excuse (« la mauvaise foi », dit Sartre)."}]},{h:"✍️ Dissertation guidée — « Être libre, est-ce faire ce que l’on veut ? »",blocks:[{t:"list",c:["**I. Oui : la liberté semble être l’absence d’obstacles.** Être libre, c’est pouvoir agir selon sa volonté, sans contrainte extérieure. La contrainte (physique, sociale) apparaît comme l’ennemie de la liberté.","**II. Mais suivre ses désirs, c’est en être l’esclave.** Mes envies sont souvent déterminées (habitudes, publicité, passions) : « faire ce que je veux » peut être obéir à des forces qui me dépassent (Spinoza). La liberté suppose donc de se **libérer de soi-même**.","**III. Dépassement : la liberté comme autonomie.** Être vraiment libre, ce n’est pas suivre tous ses désirs, mais se **donner sa propre loi** (Kant), choisir avec lucidité et assumer ses actes. La loi juste ne supprime pas la liberté : elle la garantit (Montesquieu)."]},{t:"example",h:"Conclusion",c:"Faire ce que l’on veut n’est qu’une liberté apparente si l’on ne sait pas **pourquoi** on le veut. La liberté accomplie est celle d’un sujet autonome, maître de ses désirs et responsable de ses choix."}]}],resources:[{label:"France Culture — la liberté, le déterminisme",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Spinoza, Sartre, le libre arbitre."}]},"philo-nature":{sections:[{h:"🏛️ Aux sources — nature, culture et condition humaine",blocks:[{t:"p",c:"Le mot « nature » est piégé, car il a au moins trois sens : ① l’**ensemble de ce qui existe** sans l’homme (l’environnement, le cosmos) ; ② l’**essence** d’une chose (« la nature du triangle ») ; ③ l’**inné**, ce qui est donné à la naissance, par opposition à l’**acquis** (par la culture). Confondre ces sens est la source d’innombrables erreurs de raisonnement."},{t:"p",c:"La grande question anthropologique est celle du couple **nature / culture**. **Rousseau**, dans le *Discours sur l’origine de l’inégalité*, imagine un « homme de la nature » — non pour affirmer qu’il a existé, mais pour **distinguer** ce qui, en nous, vient de la nature et ce qui vient de la société. La **perfectibilité** (la capacité de se transformer, d’apprendre, d’inventer) est ce qui arrache l’homme à l’animalité. **Lévi-Strauss**, plus tard, montrera que l’interdit de l’inceste, universel mais variable, marque précisément le **passage** de la nature à la culture."},{t:"table",head:["Sens de « nature »","Opposé","Exemple"],rows:[["L’environnement, le monde non produit par l’homme","L’artificiel, la technique","Une forêt vierge / un barrage"],["L’essence d’une chose","L’accident, le contingent","« La nature du cercle »"],["L’inné","L’acquis (la culture)","Un réflexe / une langue apprise"]]},{t:"p",c:"Reste le rapport de l’homme **à** la nature. **Descartes** assigne à la science une visée pratique : nous rendre « comme maîtres et possesseurs de la nature », pour la santé et le confort. Trois siècles plus tard, **Hans Jonas** retourne l’ambition en inquiétude : notre **puissance technique** est devenue si grande qu’elle menace la biosphère et les générations futures. D’où un **principe responsabilité** : « agis de telle sorte que les effets de ton action soient compatibles avec la permanence d’une vie authentiquement humaine sur terre »."},{t:"warning",h:"Le piège du « naturel »",c:"Passer du fait (« c’est naturel ») à la valeur (« c’est bien ») est un **sophisme naturaliste**. Beaucoup de comportements dits « naturels » sont en réalité **culturels**, donc modifiables."}]},{h:"📖 La nature dans la littérature et la pensée",blocks:[{t:"p",c:"La sensibilité à la nature a une histoire. Les **romantiques** (Rousseau déjà, puis Chateaubriand, Hugo, Lamartine avec *Le Lac*) font du paysage le miroir de l’âme et le lieu d’un ressourcement contre la société. Le XXᵉ siècle bascule dans l’**inquiétude écologique** : *Printemps silencieux* de Rachel Carson (1962) alerte sur les pesticides, et la philosophie contemporaine (Jonas, Arne Næss et l’« écologie profonde ») repense notre place dans le vivant."},{t:"p",c:"La science-fiction pousse les scénarios à l’extrême : dans de nombreux récits, l’homme, ayant épuisé ou détruit la nature terrestre, doit fuir vers d’autres mondes — façon d’interroger notre rapport de **prédation**. À l’inverse, la pensée de **Spinoza** (« *Deus sive Natura* », Dieu, c’est-à-dire la Nature) invite à ne pas se penser comme un « empire dans un empire » : l’homme est **partie** de la nature, non son souverain extérieur."},{t:"example",h:"Illustration",c:"Un barrage hydroélectrique produit une énergie « propre » mais noie une vallée et détruit un écosystème : faut-il **maîtriser** la nature (Descartes) ou en assumer la **responsabilité** (Jonas) ? Le cas concret oblige à peser les deux."},{t:"tip",h:"Repère central",c:"**Nature / culture** : ce qui définit l’homme, c’est la culture — mais elle a une base naturelle. L’un ne va pas sans l’autre."}]},{h:"✍️ Dissertation guidée — « L’homme doit-il dominer la nature ? »",blocks:[{t:"list",c:["**I. La technique invite à la maîtrise.** Livré à la nature, l’homme est démuni ; la médecine, l’agriculture, l’énergie l’en affranchissent. Descartes : nous rendre « maîtres et possesseurs de la nature » pour vivre mieux.","**II. Mais cette domination se retourne contre nous.** Épuisement des ressources, dérèglement climatique, extinctions : la maîtrise sans limite devient auto-destruction. La nature n’est pas un simple « stock » exploitable (Heidegger).","**III. Dépassement : de la domination à la responsabilité.** Il ne s’agit ni de tout exploiter ni de « revenir à la nature », mais d’une **cohabitation** réfléchie : le principe responsabilité de Jonas engage l’avenir de la vie."]},{t:"example",h:"Conclusion",c:"« Dominer » la nature au sens de la piller est une impasse ; la vraie maîtrise est celle de nos propres pouvoirs — savoir **limiter** notre puissance au nom de ce qui nous dépasse et nous suit."}]}],resources:[{label:"France Culture — nature, culture, écologie",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Rousseau, Lévi-Strauss, Jonas."}]},"philo-religion":{sections:[{h:"🏛️ Aux sources — foi, raison et sacré",blocks:[{t:"p",c:"La religion (du latin *religare*, relier, ou *relegere*, recueillir) désigne un ensemble de **croyances et de pratiques** qui relient l’homme au **sacré** — ce qui est mis à part, entouré de respect et d’interdits (par opposition au *profane*). Toute la difficulté philosophique tient dans le rapport entre la **foi** et la **raison** : sont-elles ennemies, étrangères, ou complémentaires ?"},{t:"p",c:"La distinction décisive est celle du **croire** et du **savoir**. **Croire**, c’est adhérer **sans preuve** (la foi) ; **savoir**, c’est tenir pour vrai **avec preuve** (démonstration, expérience). La foi n’est donc pas un savoir défaillant, un savoir « raté » : c’est un **autre rapport** à la vérité. **Pascal**, savant et croyant, l’exprime d’une formule célèbre : « le cœur a ses raisons que la raison ne connaît point » — il existe un ordre du cœur, irréductible à celui de la démonstration. Son fameux **pari** invite le sceptique à parier sur l’existence de Dieu, l’enjeu (l’infini) valant le risque."},{t:"table",head:["Penseur","Regard sur la religion","Idée"],rows:[["Pascal","La foi dépasse la raison sans la nier","« Le cœur a ses raisons… » ; le pari"],["Marx","Critique sociale","« Opium du peuple » : consolation qui endort"],["Freud","Critique psychologique","Illusion née d’un désir de protection"],["Durkheim","Approche sociologique","Fonction de lien social, ciment du groupe"]]},{t:"p",c:"La modernité développe une **critique** de la religion. **Marx** y voit « l’opium du peuple » : une consolation illusoire qui détourne les opprimés de transformer leur condition réelle. **Freud** en fait une **illusion** — non un simple mensonge, mais la réalisation d’un désir infantile de protection paternelle. **Durkheim**, lui, en propose une lecture **sociologique** : au-delà de la question de la vérité, la religion remplit une fonction de **cohésion**, elle fait tenir le groupe ensemble. Ces critiques n’épuisent pas la question : elles éclairent les **fonctions** de la religion sans trancher celle de la foi."},{t:"warning",h:"Piège à éviter",c:"Opposer bêtement « religion = obscurantisme » et « science = vérité ». Le sujet demande de **distinguer les plans** (croire / savoir), pas de disqualifier l’un par l’autre."}]},{h:"📖 La religion en littérature et en histoire",blocks:[{t:"p",c:"Le conflit entre foi et raison a une histoire dramatique. En **1633**, **Galilée** est condamné par l’Inquisition pour avoir soutenu, preuves à l’appui, que la Terre tourne : cas d’école d’un affrontement entre l’autorité religieuse et la démarche scientifique. **Voltaire**, au XVIIIᵉ siècle, combat le **fanatisme** et l’intolérance (*Traité sur la tolérance*, après l’affaire Calas), tout en distinguant la foi personnelle du dogmatisme persécuteur."},{t:"p",c:"La grande littérature sonde le **doute** et la foi. **Dostoïevski**, dans *Les Frères Karamazov*, met dans la bouche d’Ivan la plus redoutable objection à Dieu — le « scandale » de la souffrance des enfants innocents — et lui oppose, sans la réfuter, la foi humble d’Aliocha. **Pascal**, dans les *Pensées*, décrit l’homme partagé entre grandeur et misère, « roseau pensant » jeté dans un univers muet, et cherche dans la foi une réponse au silence des « espaces infinis »."},{t:"example",h:"Illustration",c:"Dire « je crois qu’il fera beau demain » et « je sais que 2 + 2 = 4 », ce n’est pas parler de la même façon de la vérité : l’un espère sans preuve, l’autre démontre. Toute la notion tient dans cette différence."},{t:"tip",h:"Ouverture",c:"La **laïcité** n’est pas l’hostilité à la religion, mais la neutralité de l’État qui garantit à chacun la liberté de croire — ou de ne pas croire."}]},{h:"✍️ Dissertation guidée — « La foi est-elle contraire à la raison ? »",blocks:[{t:"list",c:["**I. Elles semblent s’opposer.** La foi adhère sans preuve, la raison exige des démonstrations ; l’histoire (Galilée) montre des conflits. Croire pourrait sembler renoncer à penser.","**II. Mais elles n’ont pas le même objet.** Croire ≠ savoir : la foi ne porte pas sur des faits démontrables, mais sur un sens, une espérance. Elle relève d’un autre ordre (Pascal), que la raison ne peut ni prouver ni réfuter.","**III. Dépassement : foi et raison peuvent se compléter.** La raison peut éclairer la foi (théologie), et la foi peut donner à la raison un horizon ; l’ennemi commun n’est pas la raison ni la foi, mais le **fanatisme** — la foi qui refuse de penser."]},{t:"example",h:"Conclusion",c:"La foi n’est contraire à la raison que lorsqu’elle prétend se substituer à elle sur son propre terrain (les faits). Distinguées, elles peuvent coexister ; confondues, elles s’égarent l’une l’autre."}]}],resources:[{label:"France Culture — foi, raison, laïcité",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Pascal, la critique de la religion, la tolérance."}]},"philo-technique":{sections:[{h:"🏛️ Aux sources — l’homme, l’outil et le travail",blocks:[{t:"p",c:"La technique est l’ensemble des **procédés efficaces** par lesquels l’homme transforme la nature pour produire de l’**utile** — à distinguer de l’art (qui vise le beau) et de la science (qui vise le vrai). Le mythe grec de **Prométhée** l’exprime : l’homme, seul animal sans griffes, sans fourrure ni rapidité, reçoit en compensation le **feu** — la technique — volé aux dieux. La technique n’est donc pas un supplément : elle est **constitutive** de l’humanité. **Bergson** dira que l’intelligence est d’abord « la faculté de fabriquer des objets artificiels, en particulier des outils à faire des outils » ; l’homme est *homo faber* avant d’être *homo sapiens*."},{t:"p",c:"Le **travail**, activité par laquelle l’homme transforme la nature en se transformant lui-même, est au cœur de la réflexion. **Hegel**, dans la « dialectique du maître et de l’esclave », montre que c’est l’**esclave** — celui qui travaille et façonne le monde — qui accède à la conscience de soi, tandis que le maître, purement consommateur, en reste dépendant. **Marx** en tire une critique de l’**aliénation** : dans le travail industriel, l’ouvrier, dépossédé du produit et du sens de son activité, devient étranger à lui-même."},{t:"table",head:["Penseur","Sur la technique / le travail","Idée"],rows:[["Bergson","L’homme est homo faber","L’intelligence fabrique des outils"],["Hegel","Dialectique maître / esclave","Le travail humanise et libère"],["Marx","Critique de l’aliénation","Le travail industriel peut déshumaniser"],["Heidegger","Critique de la technique moderne","La nature réduite à un « fonds » exploitable"],["Jonas","Éthique du futur","Le principe responsabilité"]]},{t:"p",c:"**Heidegger** porte la critique la plus radicale : la technique **moderne** n’est pas un simple ensemble d’outils, c’est une manière de **dévoiler** le monde qui transforme tout — la nature, et l’homme lui-même — en « fonds » (*Bestand*), en réserve disponible et calculable. Le fleuve n’est plus contemplé, il est « sommé » de fournir de l’énergie. **Jonas**, enfin, tire les conséquences éthiques de la démesure technique : notre pouvoir engage désormais l’existence même de l’humanité future, d’où une responsabilité inédite."},{t:"tip",h:"Distinction clé",c:"**Moyen / fin.** La technique est un **moyen** ; un même couteau soigne ou tue. La vraie question n’est pas « pour ou contre la technique », mais « quel **usage** en faisons-nous ? »."}]},{h:"📖 La technique en littérature et au cinéma",blocks:[{t:"p",c:"La littérature a très tôt exprimé la **peur de la créature qui échappe au créateur**. *Frankenstein* de **Mary Shelley** (1818) — sous-titré « le Prométhée moderne » — met en scène un savant qui donne la vie à une créature qu’il ne peut plus contrôler : préfiguration de tous nos débats sur les limites de la science. *Le Meilleur des mondes* de **Huxley** imagine une humanité fabriquée, conditionnée, « heureuse » parce que dépossédée de toute liberté."},{t:"p",c:"Le cinéma prolonge l’interrogation : de *Metropolis* (Lang) à *Blade Runner* et aux récits sur l’intelligence artificielle, la question revient : la machine peut-elle nous **remplacer**, nous **asservir**, ou même devenir « humaine » ? **Rousseau**, dès le *Discours sur les sciences et les arts*, doutait déjà que le progrès technique rende les hommes **meilleurs** : la puissance croît, mais la moralité ne suit pas nécessairement."},{t:"example",h:"Illustration",c:"Le smartphone nous **libère** (tout savoir, joindre chacun, partout) et nous **asservit** (dépendance, surveillance des données, économie de l’attention). Une seule technique, deux visages : tout dépend de la maîtrise que nous en gardons."},{t:"warning",h:"Piège",c:"Croire que le **progrès technique** entraîne **automatiquement** le progrès **humain** ou moral. L’histoire du XXᵉ siècle a tragiquement démenti cet optimisme."}]},{h:"✍️ Dissertation guidée — « La technique nous libère-t-elle ? »",blocks:[{t:"list",c:["**I. La technique libère de la nécessité naturelle.** Être démuni, l’homme compense sa faiblesse : médecine, transports, moins de pénibilité. Chaque invention élargit le champ de nos possibles (Descartes).","**II. Mais elle crée de nouvelles servitudes.** Aliénation du travail (Marx), dépendance, réduction du monde à un fonds exploitable (Heidegger), risques inédits (Jonas). La libération se paie de dépendances nouvelles.","**III. Dépassement : tout dépend de l’usage et de la maîtrise.** La technique est un moyen neutre ; la vraie liberté n’est pas de posséder des machines, mais de **rester maître de nos moyens**, ce qui exige une éthique."]},{t:"example",h:"Conclusion",c:"La technique nous libère des contraintes naturelles, mais ne nous rend pas libres par elle-même : elle nous met en demeure de **choisir** ce que nous voulons en faire — et c’est là, précisément, que se joue notre liberté."}]}],resources:[{label:"France Culture — technique, travail, progrès",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Heidegger, Jonas, l’aliénation."}]},"philo-verite":{sections:[{h:"🏛️ Aux sources — vérité, opinion et démonstration",blocks:[{t:"p",c:"La vérité se définit classiquement comme l’**accord de la pensée avec son objet** (l’*adéquation*). Il faut aussitôt la distinguer de la **réalité** : la réalité est ce qui **est** ; la vérité est une propriété de nos **jugements** sur le réel. Une pierre n’est ni vraie ni fausse ; c’est ce que j’en **dis** qui peut l’être. Il faut aussi la distinguer de l’**opinion** (*doxa*) : une croyance non fondée, même partagée par tous, n’est pas un savoir."},{t:"p",c:"C’est le sens de la célèbre **allégorie de la caverne** de **Platon** : des prisonniers enchaînés prennent les **ombres** projetées sur une paroi pour la réalité ; l’un d’eux se libère, sort, découvre le soleil (l’Idée du Bien, la vérité), puis revient — et on ne le croit pas. Philosopher, c’est cette **conversion** du regard, ce difficile passage de l’apparence au réel, de l’opinion au savoir. **Descartes**, à l’aube de la modernité, propose une autre méthode : le **doute méthodique**. Douter volontairement de tout — des sens, des raisonnements, du monde — jusqu’à trouver une première certitude que le doute ne peut emporter : « je pense, donc je suis » (*cogito*)."},{t:"table",head:["Distinction","Sens","Exemple"],rows:[["Vérité / réalité","Propriété du jugement / ce qui est","« Il pleut » est vrai si, de fait, il pleut"],["Opinion / savoir","Croyance non fondée / connaissance justifiée","Croire vs démontrer"],["Vérités de raison / de fait (Leibniz)","Logiques, nécessaires / vérifiées par l’expérience","2 + 2 = 4 / « César a franchi le Rubicon »"],["Objectif / subjectif","Vaut pour l’objet, pour tous / dépend du sujet","« 20 °C » / « il fait bon »"]]},{t:"p",c:"Peut-on **tout** démontrer ? Non. Toute démonstration part d’**axiomes** que l’on ne démontre pas, sous peine de régression à l’infini. **Leibniz** distingue les **vérités de raison** (nécessaires, comme les mathématiques) et les **vérités de fait** (contingentes, vérifiées par l’expérience). Au XXᵉ siècle, **Karl Popper** ajoute un critère décisif pour la science : une théorie n’est scientifique que si elle est **réfutable** (falsifiable) — ce qui ne peut être contredit par aucune expérience n’est pas une science, mais une croyance déguisée."},{t:"warning",h:"Le piège du relativisme",c:"« À chacun sa vérité » confond le **goût** (subjectif) et la **vérité** (qui prétend valoir pour tous). Une vérité ne se décide pas au vote : la Terre ne s’est pas mise à tourner quand la majorité l’a admis."}]},{h:"📖 La vérité en littérature et dans les sciences",blocks:[{t:"p",c:"La quête de la vérité, et le mensonge, nourrissent la littérature. **Molière**, dans *Le Misanthrope*, met en scène Alceste, l’homme qui veut dire toujours la vérité, et montre combien la vie sociale repose sur de petits arrangements. **Orwell**, dans *1984*, invente la « novlangue » et le « Ministère de la Vérité » qui **réécrit** le passé : le pouvoir totalitaire ne se contente pas de mentir, il abolit l’idée même d’une vérité indépendante."},{t:"p",c:"L’histoire des sciences illustre le caractère **conquis** et **révisable** de la vérité : longtemps « la Terre est plate » ou « le Soleil tourne autour de la Terre » furent des évidences. Le progrès scientifique procède par **ruptures** (Bachelard parle d’« obstacles épistémologiques » à franchir) : la vérité d’aujourd’hui corrige celle d’hier, sans que cela ruine l’idée de vérité — au contraire, c’est le signe d’une pensée qui se **contrôle** elle-même."},{t:"example",h:"Illustration",c:"Le doute cartésien n’est pas le scepticisme (qui doute pour ne rien conclure) : c’est un **outil**, une étape pour atteindre le certain. On doute afin de mieux savoir."},{t:"tip",h:"Repère central",c:"**Opinion / savoir.** Une vérité ne dépend pas du nombre de gens qui y croient, mais de ce qui la **fonde** (preuve, expérience, démonstration)."}]},{h:"✍️ Dissertation guidée — « Toutes les opinions se valent-elles ? »",blocks:[{t:"list",c:["**I. Chacun a droit à son opinion.** La liberté de pensée et d’expression suppose de respecter la diversité des points de vue ; nul ne détient un monopole de la vérité, et le dogmatisme est dangereux.","**II. Mais l’opinion n’est pas le savoir.** Une opinion non fondée ne vaut pas une connaissance démontrée : sur un fait, toutes les opinions ne se valent pas (Platon oppose la *doxa* à l’*épistémè*). Confondre les deux, c’est ouvrir la porte à la désinformation.","**III. Dépassement.** Respecter le **droit** d’avoir une opinion n’oblige pas à tenir toutes les opinions pour **également vraies**. La vérité se cherche par l’argumentation et la preuve ; le débat n’a de sens que s’il vise, au-delà des opinions, quelque chose de vrai."]},{t:"example",h:"Conclusion",c:"Toutes les opinions ont un droit égal à s’exprimer, mais elles n’ont pas une valeur égale devant la vérité : c’est même parce que la vérité existe que la discussion vaut la peine d’être menée."}]}],resources:[{label:"France Culture — vérité, science, opinion",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Platon, Descartes, Popper, Bachelard."}]},"philo-methode":{sections:[{h:"🧭 La dissertation — méthode complète et détaillée",blocks:[{t:"p",c:"La dissertation de philosophie n’est ni un exposé de cours, ni une opinion personnelle : c’est une **démonstration** organisée qui répond à **une** question précise. Le correcteur n’attend pas que vous « sachiez » beaucoup de choses, mais que vous sachiez **penser** — analyser, problématiser, argumenter. Voici la marche à suivre, étape par étape."},{t:"list",c:["**1. Analyser le sujet.** Définir chaque mot important (souvent plusieurs sens possibles), repérer les présupposés, délimiter le champ. Un mot mal défini, et toute la copie déraille.","**2. Problématiser.** Transformer le sujet en un **problème** : montrer que la réponse évidente se heurte à une objection, qu’il y a une **tension** entre deux réponses également défendables. C’est le cœur de l’introduction.","**3. Construire un plan progressif.** Souvent en trois moments : **thèse** (oui, parce que…) — **antithèse** (mais…) — **dépassement** (en réalité…). Chaque partie doit **faire avancer** la réflexion, pas seulement juxtaposer des avis.","**4. Argumenter.** Chaque sous-partie = une **idée** + un **argument** qui la justifie + un **exemple** ou un **auteur** qui l’illustre. On explique toujours ce que l’exemple apporte.","**5. Conclure.** Répondre **clairement** au problème posé (surtout pas « ça dépend » sans plus), puis, éventuellement, ouvrir sur une nouvelle question."]},{t:"example",h:"Introduction rédigée — « La technique nous libère-t-elle ? »",c:"Chaque jour, le GPS, le smartphone ou la machine à laver nous épargnent mille efforts : la technique paraît être une puissance de libération. Pourtant, beaucoup se sentent esclaves de leurs écrans ou menacés par les machines. La **technique** désigne l’ensemble des procédés efficaces par lesquels l’homme transforme la nature ; **libérer**, c’est affranchir d’une contrainte. Le problème est donc le suivant : si la technique nous délivre des contraintes naturelles, ne crée-t-elle pas de nouvelles dépendances ? Nous verrons d’abord qu’elle libère de la nature, puis qu’elle peut asservir, enfin que tout dépend de l’usage que nous en faisons."},{t:"warning",h:"Les deux pièges mortels",c:"Le **hors-sujet** (on répond à côté, faute d’avoir analysé le sujet) et la **récitation** (on déroule le cours sans problématiser). Revenez sans cesse à **la** question posée."}]},{h:"📖 L’explication de texte — méthode et exemple traité",blocks:[{t:"p",c:"L’explication de texte consiste à **rendre compte** fidèlement d’un texte philosophique, puis à en **discuter** la portée. On ne donne pas son avis d’emblée : on suit d’abord, pas à pas, la pensée de l’auteur, comme un guide qui éclaire chaque passage."},{t:"list",c:["**① Dégager la thèse** : que veut prouver l’auteur ? En une phrase.","**② Repérer les mouvements** : découper le texte en étapes logiques (les « moments » de l’argumentation), repérés par les connecteurs (« mais », « donc », « car », « ainsi »).","**③ Expliquer** : reformuler et éclairer chaque étape, définir les concepts employés, montrer comment l’auteur passe de l’un à l’autre.","**④ Éclairer les exemples** et le vocabulaire technique.","**⑤ Discuter** : la thèse est-elle convaincante ? Quelles objections ? Quelle portée ?"]},{t:"example",h:"Exemple traité — Pascal, le « roseau pensant »",c:"« L’homme n’est qu’un roseau, le plus faible de la nature ; mais c’est un roseau pensant. » **Thèse** : la grandeur de l’homme tient non à sa force mais à sa pensée. **Mouvements** : (a) « le plus faible de la nature » = la fragilité physique (un souffle suffit à le tuer) ; (b) le « **mais** » renverse tout : « roseau **pensant** » = la pensée fait sa dignité. **Explication** : l’homme est supérieur à l’univers qui l’écrase parce qu’il **le sait**, tandis que l’univers l’ignore. **Discussion** : où placer la dignité humaine ? Dans la conscience plutôt que dans la force — ce qui relie ce texte aux notions de conscience et de nature."},{t:"tip",h:"Réflexe",c:"Souligner les **connecteurs logiques** (« mais », « donc », « car ») : ils dessinent la charpente du texte et vous donnent le plan de votre explication."}]},{h:"👤 Galerie d’auteurs — une idée par philosophe",blocks:[{t:"p",c:"Inutile de connaître des dizaines d’auteurs : quelques-uns, **bien maîtrisés** (une idée, une formule, un exemple chacun), suffisent à nourrir n’importe quelle copie. Voici une galerie de repères, de l’Antiquité au XXᵉ siècle."},{t:"table",head:["Auteur","Idée clé","Notions concernées"],rows:[["Platon","Allégorie de la caverne : des ombres à la vérité","Vérité, art"],["Aristote","Justice distributive et corrective, l’équité qui corrige la loi ; l’homme « animal politique »","Justice"],["Épictète","Distinguer ce qui dépend de nous","Liberté, bonheur"],["Descartes","Doute méthodique, cogito, maîtrise de la nature","Vérité, technique"],["Pascal","Le « roseau pensant » ; les raisons du cœur","Religion, nature"],["Spinoza","La liberté comme illusion (déterminisme)","Liberté"],["Rousseau","Nature / culture ; le contrat social","Justice, liberté, nature"],["Kant","L’autonomie ; le jugement de goût désintéressé","Liberté, art"],["Hegel","Dialectique maître / esclave ; l’art manifeste l’Esprit","Technique, art"],["Marx","Aliénation ; religion « opium du peuple »","Technique, religion"],["Nietzsche","Critique de la morale et des « arrière-mondes »","Vérité, religion"],["Freud","L’inconscient ; la religion comme illusion","Conscience, religion"],["Heidegger","La technique moderne réduit le monde à un « fonds »","Technique"],["Sartre","L’existence précède l’essence : liberté et responsabilité","Liberté"],["Arendt","La « banalité du mal » ; l’action politique","Justice, politique"],["Jonas","Le principe responsabilité envers l’avenir","Nature, technique"]]},{t:"tip",h:"Stratégie payante",c:"Reliez chaque auteur à **une notion** et à **un exemple**. Le jour du bac, vous mobiliserez la bonne référence au bon endroit, expliquée — jamais plaquée."}]}],resources:[{label:"Éduscol — sujets & annales de philosophie (voie techno)",url:"https://eduscol.education.fr/",kind:"doc",note:"Le programme officiel et des sujets pour s’entraîner."}]}},m=Object.freeze(Object.defineProperty({__proto__:null,default:l},Symbol.toStringTag,{value:"Module"})),u={"philo-methode-tri":2,"philo-methode-ordre2":1},h=Object.freeze(Object.defineProperty({__proto__:null,default:u},Symbol.toStringTag,{value:"Module"})),e="philosophie",i="Philosophie",t="Philo",s="🦉",n="#9333ea",r="Chaque notion expliquée par un exemple réel, puis problématisée.",a=[{id:"philo-art",name:"L’art",short:"L’art",keywords:"art beau esthétique création imitation Duchamp Platon Hegel Kant œuvre artisanat goût",intro:"Un urinoir industriel signé peut-il devenir une œuvre exposée dans les plus grands musées ? La notion d’art interroge ce qui fait une œuvre, ce à quoi elle sert, et si le beau vaut pour tous ou seulement pour moi.",cours:[{h:"🎨 Comprendre — l’art par l’exemple (la « Fontaine » de Duchamp)",blocks:[{t:"example",h:"Situation",c:"En 1917, Marcel Duchamp expose un simple urinoir industriel, retourné et signé « R. Mutt », qu’il intitule « Fontaine ». Un objet ordinaire devient une œuvre discutée dans le monde entier."},{t:"list",c:["**La distinction clé** : *art / artisanat*. L’artisan fabrique des objets **utiles** en suivant un modèle ; l’artiste crée une œuvre **singulière**, qui vaut pour elle-même et non pour son usage.","**Beau / agréable** : l’agréable **plaît aux sens** (un plat, une température) ; le beau prétend, lui, valoir **au-delà** de mon plaisir immédiat.","Avec Duchamp, ce n’est plus l’objet ni le savoir-faire qui font l’œuvre, mais le **geste** de l’artiste et le **regard** de l’institution (le musée)."]},{t:"tip",h:"Réflexe",c:"Face à un sujet sur l’art, demande-toi d’abord : de quoi parle-t-on — de l’objet, de l’activité de création, ou du jugement de goût ?"}]},{h:"🤔 Le problème — l’art imite-t-il ou crée-t-il ?",blocks:[{t:"p",c:"On attend souvent de l’art qu’il **ressemble** au réel. Mais est-ce là sa vraie fonction ?"},{t:"list",c:["**Thèse 1 — l’art imite (et trompe)** : pour **Platon**, l’art n’est qu’une **copie de copie**, une illusion qui nous éloigne de la vérité.","**Thèse 2 — l’art révèle** : pour **Hegel**, l’œuvre **manifeste l’esprit** ; elle dit une vérité sur l’homme que le réel brut ne montre pas.","**Le beau est-il subjectif ?** Pour **Kant**, dire « c’est beau » n’est pas dire « ça me plaît » : le jugement de goût est **subjectif mais prétend valoir pour tous** (universalité sans concept)."]},{t:"tip",h:"Citation utile",c:"« L’art ne reproduit pas le visible, il rend visible. » (Paul Klee)"}]},{h:"🎓 Approfondir & au bac",blocks:[{t:"list",c:["**À quoi sert l’art ?** Émouvoir, faire penser, critiquer la société, donner forme à l’indicible — pas seulement décorer.","**Piège** : « c’est beau » n’est pas un argument. Il faut **expliquer** ce que l’œuvre produit et pourquoi."]},{t:"example",h:"Sujet type",c:"« L’œuvre d’art n’a-t-elle pour but que d’être belle ? » → I. L’art vise le beau — II. Mais il dit aussi une vérité, il dérange — III. Sa valeur tient à ce qu’il **donne à penser**, pas seulement à plaire."},{t:"tip",h:"Repères mobilisables",c:"Beau / agréable · art / technique · objectif / subjectif."}]}],essentiel:["Distinction clé : **art / artisanat** (l’œuvre est singulière et vaut pour elle-même, pas pour son usage).","Deux thèses : l’art **imite** et trompe (**Platon**) / l’art **révèle** une vérité (**Hegel**).","Le **beau** n’est pas l’**agréable** : pour **Kant**, le goût est subjectif mais prétend valoir pour tous."],resources:[{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Cherche des émissions sur l’art et le beau."},{label:"Lumni — Philosophie",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « l’art », « le beau »."}],games:[{id:"philo-art-flash",type:"flashcard",title:"Flashcards — L’art",icon:"🃏",cards:[{front:"Art / artisanat",back:"L’artisan fait de l’utile en suivant un modèle ; l’artiste crée une œuvre singulière."},{front:"Platon et l’art",back:"L’art n’est qu’une imitation trompeuse (copie de copie), il éloigne de la vérité."},{front:"Hegel et l’art",back:"L’œuvre manifeste l’esprit : elle révèle une vérité sur l’homme."},{front:"Kant et le beau",back:"Le jugement de goût est subjectif mais prétend valoir pour tous."},{front:"« L’art rend visible »",back:"Klee : l’art ne copie pas le réel, il fait voir autrement."}]},{id:"philo-art-assoc",type:"association",title:"Association — Art",icon:"🔗",pairs:[{left:"Platon",right:"L’art imite (illusion)"},{left:"Hegel",right:"L’art révèle une vérité"},{left:"Kant",right:"Le beau : subjectif mais universel"},{left:"Duchamp",right:"L’objet consacré par l’artiste"}]},{id:"philo-art-qcm",type:"qcm",title:"QCM — L’art",icon:"❓",questions:[{q:"La distinction « art / artisanat » oppose…",choices:["une œuvre singulière / un objet utile reproduit","le beau / le laid","le vrai / le faux","la cause / la fin"],answer:0,explain:"L’artisan reproduit de l’utile ; l’artiste crée du singulier."},{q:"Pour Platon, l’art est…",choices:["une imitation trompeuse du réel","la plus haute vérité","une technique utile","un savoir démontré"],answer:0,explain:"L’art est une copie de copie, une illusion."},{q:"Pour Kant, « c’est beau » signifie…",choices:["un jugement subjectif qui prétend valoir pour tous","exactement « ça me plaît »","une vérité démontrable","une simple mode"],answer:0,explain:"Universalité sans concept du jugement de goût."},{q:"« L’art ne reproduit pas le visible, il rend visible » est de…",choices:["Paul Klee","Platon","Descartes","Rousseau"],answer:0,explain:"Formule de Klee sur le pouvoir de révélation de l’art."}]},{id:"philo-art-vf",type:"vraifaux",title:"Vrai / Faux — L’art",icon:"⚡",questions:[{statement:"Le beau et l’agréable sont la même chose.",answer:!1,explain:"Faux : l’agréable plaît aux sens ; le beau prétend valoir au-delà."},{statement:"Pour Hegel, l’œuvre d’art peut révéler une vérité.",answer:!0,explain:"Vrai : l’art manifeste l’esprit."},{statement:"Dire « c’est beau » suffit comme argument au bac.",answer:!1,explain:"Faux : il faut expliquer ce que l’œuvre produit."}]}]},{id:"philo-justice",name:"La justice",short:"La justice",keywords:"justice droit loi équité légal légitime égalité Rosa Parks Aristote Rousseau désobéissance",intro:"En 1955, Rosa Parks enfreint une loi bien réelle en refusant de céder sa place… mais une loi que l’histoire jugera injuste. La justice interroge le rapport entre la loi, l’équité et ce qui est vraiment juste.",cours:[{h:"⚖️ Comprendre — la justice par l’exemple (Rosa Parks)",blocks:[{t:"example",h:"Situation",c:"À Montgomery (États-Unis, 1955), Rosa Parks refuse de céder sa place à un passager blanc dans le bus. Elle enfreint la loi de ségrégation en vigueur."},{t:"list",c:["**La distinction décisive** : *légal / légitime*. Est **légal** ce qui est conforme à la loi ; est **légitime** ce qui est conforme à la **justice**. La ségrégation était **légale** mais **illégitime**.","**Justice = égalité ?** **Aristote** distingue l’égalité **arithmétique** (la même chose pour tous) et l’égalité **proportionnelle** (à chacun selon son mérite ou son besoin).","**L’équité** corrige la loi générale quand elle devient injuste dans un cas particulier."]},{t:"tip",h:"À ne pas confondre",c:"**La justice** (idéal moral et politique) ≠ **la justice** au sens des tribunaux (l’institution)."}]},{h:"🤔 Le problème — peut-il être juste de désobéir ?",blocks:[{t:"list",c:["**Thèse 1 — obéir à la loi** : la loi garantit l’ordre ; si chacun juge « sa » loi injuste, c’est l’anarchie.","**Thèse 2 — désobéir à une loi injuste** : la **désobéissance civile** enfreint publiquement une loi au nom d’une justice supérieure (Rosa Parks, Gandhi, Thoreau).","**La force fait-elle le droit ?** Pour **Rousseau**, non : « le plus fort n’est jamais assez fort pour être toujours le maître, s’il ne transforme sa force en droit ». Le droit doit **limiter** la force."]},{t:"tip",h:"Citation utile",c:"« Le plus fort n’est jamais assez fort pour être toujours le maître, s’il ne transforme sa force en droit. » (Rousseau)"}]},{h:"🎓 Approfondir & au bac",blocks:[{t:"list",c:["**Égalité ou équité ?** Traiter tout le monde pareil peut être injuste (ex. un même impôt pour tous les revenus). L’équité **adapte** au cas.","**Piège** : ne pas réduire la justice à la légalité — c’est justement l’écart entre les deux qui fait le sujet."]},{t:"example",h:"Sujet type",c:"« Est-il juste d’obéir à toutes les lois ? » → I. La loi rend la justice possible — II. Mais une loi peut être injuste (légal ≠ légitime) — III. La désobéissance civile, ou comment contester **au nom** de la justice."},{t:"tip",h:"Repères mobilisables",c:"Légal / légitime · égalité / équité · en théorie / en pratique."}]}],essentiel:["Distinction décisive : **légal / légitime** (conforme à la loi ≠ conforme à la justice).","**Aristote** : égalité **arithmétique** (pareil pour tous) vs **proportionnelle** ; l’**équité** corrige la loi.","**Rousseau** : la force seule ne fonde pas le droit ; désobéir peut être juste (désobéissance civile)."],resources:[{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Cherche « justice », « désobéissance civile »."},{label:"Lumni — Philosophie",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « la justice », « le droit »."}],games:[{id:"philo-justice-flash",type:"flashcard",title:"Flashcards — La justice",icon:"🃏",cards:[{front:"Légal / légitime",back:"Conforme à la loi / conforme à la justice : une loi peut être l’un sans l’autre."},{front:"Égalité chez Aristote",back:"Arithmétique (pareil pour tous) vs proportionnelle (à chacun selon…)."},{front:"Équité",back:"Corriger la loi générale quand elle est injuste dans un cas précis."},{front:"Désobéissance civile",back:"Enfreindre publiquement une loi injuste au nom d’une justice supérieure."},{front:"Rousseau et la force",back:"La force ne fait pas le droit : il faut transformer la force en droit."}]},{id:"philo-justice-assoc",type:"association",title:"Association — Justice",icon:"🔗",pairs:[{left:"Légal",right:"Conforme à la loi"},{left:"Légitime",right:"Conforme à la justice"},{left:"Aristote",right:"Égalité proportionnelle / équité"},{left:"Rousseau",right:"La force ne fonde pas le droit"}]},{id:"philo-justice-qcm",type:"qcm",title:"QCM — La justice",icon:"❓",questions:[{q:"« Légal / légitime » oppose…",choices:["conforme à la loi / conforme à la justice","le vrai / le faux","le beau / le laid","la cause / la fin"],answer:0,explain:"Une loi peut être légale sans être légitime."},{q:"L’équité consiste à…",choices:["corriger la loi générale dans un cas particulier","appliquer la même règle à tous sans exception","supprimer toutes les lois","juger au hasard"],answer:0,explain:"L’équité adapte la justice au cas concret."},{q:"La désobéissance civile, c’est…",choices:["enfreindre publiquement une loi jugée injuste","voler discrètement","ignorer toutes les règles","faire la loi soi-même"],answer:0,explain:"Un acte public au nom d’une justice supérieure."},{q:"Pour Rousseau, la force…",choices:["ne suffit pas à fonder le droit","fait toujours le droit","est la justice même","n’existe pas"],answer:0,explain:"Le droit doit limiter la force, pas la servir."}]},{id:"philo-justice-vf",type:"vraifaux",title:"Vrai / Faux — La justice",icon:"⚡",questions:[{statement:"« Légal » et « légitime » sont exactement synonymes.",answer:!1,explain:"Faux : une loi peut être légale sans être légitime."},{statement:"Traiter tout le monde à l’identique est toujours juste.",answer:!1,explain:"Faux : parfois l’équité impose d’adapter au cas."},{statement:"La désobéissance civile invoque une justice supérieure à la loi.",answer:!0,explain:"Vrai : c’est son principe même."}]}]},{id:"philo-liberte",name:"La liberté",short:"La liberté",keywords:"liberté autonomie licence déterminisme responsabilité Spinoza Sartre Kant Montesquieu libre arbitre",intro:"« Je suis libre de fumer si je veux » — mais le fumeur dépendant agit-il librement, ou son addiction décide-t-elle à sa place ? La liberté interroge ce que signifie vraiment agir par soi-même.",cours:[{h:"🕊️ Comprendre — la liberté par l’exemple (le fumeur)",blocks:[{t:"example",h:"Situation",c:"« Je suis libre de fumer si je veux. » Mais ce fumeur est dépendant à la nicotine : agit-il vraiment librement ?"},{t:"list",c:["**La distinction clé** : *liberté / licence*. La liberté n’est pas faire **n’importe quoi** au gré de ses envies (licence), mais l’**autonomie** : se donner à soi-même sa propre loi (**Kant**).","**Liberté / déterminisme** : le déterminisme affirme que **tout a une cause**. Le fumeur « choisit »… ou est-il déterminé par son addiction ?","Être libre suppose donc de ne pas être **esclave** de ses désirs immédiats."]},{t:"tip",h:"Réflexe",c:"Distingue toujours « faire ce que je veux » (licence) et « être maître de moi » (autonomie)."}]},{h:"🤔 Le problème — sommes-nous vraiment libres ?",blocks:[{t:"list",c:["**Thèse 1 — nous nous croyons libres à tort** : **Spinoza** : nous **ignorons les causes** qui nous déterminent, comme une pierre lancée qui se croirait libre de tomber.","**Thèse 2 — nous sommes condamnés à être libres** : **Sartre** : il n’y a pas de nature humaine pour nous excuser ; nous sommes **responsables** de ce que nous faisons de nous-mêmes.","**Liberté et loi** : la loi limite-t-elle ou **garantit**-elle la liberté ? « La liberté est le droit de faire tout ce que les lois permettent » (**Montesquieu**) — sans loi, règne la liberté du plus fort."]},{t:"tip",h:"Citation utile",c:"« L’homme est condamné à être libre. » (Sartre) — libre = responsable, sans excuse."}]},{h:"🎓 Approfondir & au bac",blocks:[{t:"list",c:["**Liberté et responsabilité** vont ensemble : si je suis libre, je réponds de mes actes.","**Piège** : confondre liberté et absence totale de contrainte. Les règles que l’on se donne (autonomie) sont une forme supérieure de liberté."]},{t:"example",h:"Sujet type",c:"« Être libre, est-ce faire ce que l’on veut ? » → I. Oui, la liberté semble être l’absence de contrainte — II. Mais suivre ses désirs, c’est en être esclave (déterminisme) — III. La vraie liberté est l’**autonomie**, se donner sa propre loi."},{t:"tip",h:"Repères mobilisables",c:"Liberté / libre arbitre · contrainte / obligation · cause / fin."}]}],essentiel:["Distinction clé : **autonomie / licence** (se donner sa loi ≠ faire n’importe quoi).","**Spinoza** : nous nous croyons libres car nous ignorons les causes ; **Sartre** : « condamnés à être libres », donc responsables.","**Montesquieu** : la loi ne supprime pas la liberté, elle la **garantit**."],resources:[{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Cherche « liberté », « déterminisme »."},{label:"Lumni — Philosophie",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « la liberté », « le libre arbitre »."}],games:[{id:"philo-liberte-flash",type:"flashcard",title:"Flashcards — La liberté",icon:"🃏",cards:[{front:"Autonomie / licence",back:"Se donner sa propre loi (Kant) / faire n’importe quoi."},{front:"Déterminisme",back:"Tout a une cause : interroge la réalité de notre liberté."},{front:"Spinoza",back:"Nous nous croyons libres car nous ignorons les causes qui nous déterminent."},{front:"Sartre",back:"« L’homme est condamné à être libre » : responsable, sans excuse."},{front:"Montesquieu",back:"La liberté, c’est pouvoir faire ce que les lois permettent."}]},{id:"philo-liberte-assoc",type:"association",title:"Association — Liberté",icon:"🔗",pairs:[{left:"Spinoza",right:"On ignore les causes qui nous déterminent"},{left:"Sartre",right:"Condamné à être libre"},{left:"Kant",right:"Liberté = autonomie"},{left:"Montesquieu",right:"La loi garantit la liberté"}]},{id:"philo-liberte-qcm",type:"qcm",title:"QCM — La liberté",icon:"❓",questions:[{q:"L’autonomie, c’est…",choices:["se donner à soi-même sa propre loi","faire tout ce qui passe par la tête","obéir aveuglément","ne rien décider"],answer:0,explain:"Autonomie ≠ licence."},{q:"Spinoza explique que nous nous croyons libres parce que…",choices:["nous ignorons les causes qui nous déterminent","nous sommes réellement sans cause","la liberté n’existe pas du tout","Dieu le veut"],answer:0,explain:"La pierre lancée se croirait libre de tomber."},{q:"« L’homme est condamné à être libre » est de…",choices:["Sartre","Platon","Descartes","Hegel"],answer:0,explain:"Formule de Sartre : liberté = responsabilité."},{q:"Pour Montesquieu, la liberté…",choices:["consiste à faire ce que les lois permettent","est l’absence de toute loi","appartient au plus fort","est impossible"],answer:0,explain:"Sans loi, c’est la liberté du plus fort qui écrase les autres."}]},{id:"philo-liberte-vf",type:"vraifaux",title:"Vrai / Faux — La liberté",icon:"⚡",questions:[{statement:"Être libre, c’est nécessairement l’absence de toute règle.",answer:!1,explain:"Faux : l’autonomie (se donner sa loi) est une liberté supérieure."},{statement:"Pour Sartre, nous sommes responsables de ce que nous faisons de nous.",answer:!0,explain:"Vrai : pas de nature humaine pour nous excuser."},{statement:"La liberté peut être interrogée face au déterminisme.",answer:!0,explain:"Vrai : si tout a une cause, sommes-nous libres ?"}]}]},{id:"philo-nature",name:"La nature",short:"La nature",keywords:"nature culture environnement Descartes Rousseau Jonas écologie inné acquis sophisme naturaliste",intro:"Un barrage produit une électricité « propre » mais noie une vallée entière. Faut-il maîtriser la nature ou la respecter ? Et « c’est naturel » veut-il dire « c’est bien » ?",cours:[{h:"🌿 Comprendre — la nature par l’exemple (le barrage)",blocks:[{t:"example",h:"Situation",c:"Un barrage hydroélectrique produit une énergie « propre »… mais détruit un écosystème entier. Faut-il « respecter la nature » ou la mettre à notre service ?"},{t:"list",c:["**Trois sens du mot « nature »** : ① ce qui n’est pas produit par l’homme (l’environnement) ; ② l’**essence** d’une chose (« la nature de… ») ; ③ l’**inné**, par opposition à l’**acquis** (par culture).","**La distinction clé** : *nature / culture*. L’homme est un être de **culture** (langage, techniques, institutions) qui se distingue de l’animal.","**Rousseau** oppose l’homme **naturel** et l’homme **social** (transformé par la vie en société)."]},{t:"tip",h:"Réflexe",c:"Précise toujours **quel sens** de « nature » est en jeu : l’environnement, l’essence, ou l’inné."}]},{h:"🤔 Le problème — maîtriser ou respecter la nature ?",blocks:[{t:"list",c:["**Thèse 1 — maîtriser** : **Descartes** veut nous rendre « comme **maîtres et possesseurs** de la nature » (pour la santé, le confort).","**Thèse 2 — se responsabiliser** : **Hans Jonas** oppose un **principe responsabilité** : notre puissance technique menace la nature et les générations futures.","**Piège du « naturel »** : passer du fait (naturel) à la valeur (bien) est un **sophisme naturaliste**. Beaucoup de comportements dits « naturels » sont en réalité **culturels**, donc modifiables."]},{t:"tip",h:"À retenir",c:"« C’est dans la nature humaine » sert souvent à justifier ce qui n’est qu’une **habitude culturelle**."}]},{h:"🎓 Approfondir & au bac",blocks:[{t:"list",c:["**Nature / culture** est le repère central : ce qui définit l’homme, c’est la culture (mais elle a une base naturelle).","**Enjeu actuel** : l’écologie repose la question de notre rapport à la nature (maîtrise vs respect)."]},{t:"example",h:"Sujet type",c:"« L’homme doit-il dominer la nature ? » → I. La technique nous invite à la maîtriser (Descartes) — II. Mais cette maîtrise crée des dangers — III. Une responsabilité nouvelle envers la nature (Jonas)."},{t:"tip",h:"Repères mobilisables",c:"Nature / culture · cause / fin · en théorie / en pratique."}]}],essentiel:["Distinction clé : **nature / culture** (ce qui n’est pas de l’homme / ce qu’il produit et transmet).","**Descartes** : maîtriser la nature ; **Jonas** : en être responsable (générations futures).","Attention au **sophisme naturaliste** : « naturel » ne veut pas dire « juste »."],resources:[{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Cherche « nature et culture », « écologie »."},{label:"Lumni — Philosophie",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « nature / culture »."}],games:[{id:"philo-nature-flash",type:"flashcard",title:"Flashcards — La nature",icon:"🃏",cards:[{front:"Nature / culture",back:"Ce qui n’est pas produit par l’homme / ce qu’il produit et transmet."},{front:"Descartes",back:"Nous rendre « comme maîtres et possesseurs de la nature »."},{front:"Jonas",back:"Principe responsabilité : protéger la nature et les générations futures."},{front:"Sophisme naturaliste",back:"Confondre le fait (naturel) et la valeur (bien)."},{front:"Rousseau",back:"Distingue l’homme naturel et l’homme social."}]},{id:"philo-nature-assoc",type:"association",title:"Association — Nature",icon:"🔗",pairs:[{left:"Descartes",right:"Maîtres et possesseurs de la nature"},{left:"Jonas",right:"Principe responsabilité"},{left:"Rousseau",right:"Homme naturel / homme social"},{left:"Sophisme naturaliste",right:"Confondre fait et valeur"}]},{id:"philo-nature-qcm",type:"qcm",title:"QCM — La nature",icon:"❓",questions:[{q:"La distinction centrale de la notion « nature » est…",choices:["nature / culture","légal / légitime","croire / savoir","beau / agréable"],answer:0,explain:"C’est le repère clé pour définir l’homme."},{q:"« Maîtres et possesseurs de la nature » est de…",choices:["Descartes","Jonas","Sartre","Kant"],answer:0,explain:"Descartes assigne à la science une visée pratique."},{q:"Dire « c’est naturel donc c’est bien » est…",choices:["un sophisme (confondre fait et valeur)","une démonstration valable","une loi scientifique","un repère"],answer:0,explain:"C’est le sophisme naturaliste."},{q:"Le principe responsabilité de Jonas concerne…",choices:["les générations futures et l’environnement","les seuls contrats commerciaux","la logique pure","le beau"],answer:0,explain:"Notre puissance technique crée des devoirs nouveaux."}]},{id:"philo-nature-vf",type:"vraifaux",title:"Vrai / Faux — La nature",icon:"⚡",questions:[{statement:"Tout ce qui est « naturel » est forcément bon ou juste.",answer:!1,explain:"Faux : c’est le sophisme naturaliste."},{statement:"La culture distingue l’homme de l’animal.",answer:!0,explain:"Vrai : langage, techniques, institutions."},{statement:"Descartes proposait de renoncer à toute maîtrise de la nature.",answer:!1,explain:"Faux : il voulait au contraire nous en rendre maîtres."}]}]},{id:"philo-religion",name:"La religion",short:"La religion",keywords:"religion foi raison sacré croire savoir Galilée Pascal Marx Freud Durkheim",intro:"En 1633, Galilée est condamné pour avoir soutenu, preuves à l’appui, que la Terre tourne. Un cas d’école du rapport — parfois tendu — entre la foi et la raison.",cours:[{h:"✝️ Comprendre — la religion par l’exemple (Galilée)",blocks:[{t:"example",h:"Situation",c:"En 1633, Galilée est condamné par l’Église pour avoir soutenu que la Terre tourne autour du Soleil. Conflit entre la foi et la raison scientifique."},{t:"list",c:["**Définir** : la religion est un ensemble de **croyances et de pratiques** reliant l’homme au **sacré** (du latin *religare*, relier).","**La distinction clé** : *croire / savoir*. **Croire**, c’est adhérer **sans preuve** (la foi) ; **savoir**, c’est tenir pour vrai **avec preuve** (démonstration, expérience).","La foi n’est pas un savoir raté : c’est un **autre rapport** à la vérité."]},{t:"tip",h:"Réflexe",c:"Ne réduis pas la religion à une « erreur » : distingue foi (croire) et science (savoir) sans les confondre."}]},{h:"🤔 Le problème — foi et raison s’opposent-elles ?",blocks:[{t:"list",c:["**Thèse 1 — elles se complètent** : **Pascal** : « le cœur a ses raisons que la raison ne connaît point » — la foi **dépasse** la raison sans la contredire.","**Thèse 2 — regards critiques** : **Marx** (« opium du peuple » : une consolation qui endort la révolte) ; **Freud** (une **illusion** née d’un désir de protection).","**Fonction sociale** : **Durkheim** montre que la religion est un puissant **lien social** qui soude le groupe."]},{t:"tip",h:"Citation utile",c:"« Le cœur a ses raisons que la raison ne connaît point. » (Pascal)"}]},{h:"🎓 Approfondir & au bac",blocks:[{t:"list",c:["**Croire / savoir** est le repère central : il évite de juger la foi avec les critères de la science.","**Piège** : opposer bêtement « religion = obscurantisme » et « science = vérité ». Le sujet demande de **nuancer**."]},{t:"example",h:"Sujet type",c:"« La foi est-elle contraire à la raison ? » → I. Elles semblent s’opposer (Galilée) — II. Mais elles n’ont pas le même objet (croire ≠ savoir) — III. La foi peut dépasser la raison (Pascal), la raison peut l’éclairer."},{t:"tip",h:"Repères mobilisables",c:"Croire / savoir · universel / particulier · objectif / subjectif."}]}],essentiel:["Distinction clé : **croire / savoir** (adhérer sans preuve / tenir pour vrai avec preuve).","**Pascal** : la foi dépasse la raison sans la nier ; regards critiques de **Marx** et **Freud**.","**Durkheim** : la religion est aussi un puissant **lien social**."],resources:[{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Cherche « foi et raison », « religion »."},{label:"Lumni — Philosophie",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « la religion », « croire et savoir »."}],games:[{id:"philo-religion-flash",type:"flashcard",title:"Flashcards — La religion",icon:"🃏",cards:[{front:"Croire / savoir",back:"Adhérer sans preuve (foi) / tenir pour vrai avec preuve."},{front:"Religion",back:"Croyances et pratiques reliant l’homme au sacré (religare : relier)."},{front:"Pascal",back:"« Le cœur a ses raisons que la raison ne connaît point. »"},{front:"Marx",back:"La religion, « opium du peuple » : une consolation qui endort."},{front:"Durkheim",back:"La religion comme lien social, ciment du groupe."}]},{id:"philo-religion-assoc",type:"association",title:"Association — Religion",icon:"🔗",pairs:[{left:"Pascal",right:"Les raisons du cœur"},{left:"Marx",right:"Opium du peuple"},{left:"Freud",right:"La religion comme illusion"},{left:"Durkheim",right:"La religion, lien social"}]},{id:"philo-religion-qcm",type:"qcm",title:"QCM — La religion",icon:"❓",questions:[{q:"La distinction « croire / savoir » sépare…",choices:["adhérer sans preuve / tenir pour vrai avec preuve","le beau / le laid","le légal / le légitime","la cause / la fin"],answer:0,explain:"Croire = foi ; savoir = preuve."},{q:"« Le cœur a ses raisons… » est de…",choices:["Pascal","Marx","Durkheim","Descartes"],answer:0,explain:"La foi dépasse la raison sans la nier."},{q:"Pour Marx, la religion est…",choices:["« l’opium du peuple »","une science exacte","un simple loisir","une démonstration"],answer:0,explain:"Une consolation qui endort la révolte."},{q:"Durkheim insiste surtout sur la fonction…",choices:["de lien social de la religion","purement individuelle","scientifique","esthétique"],answer:0,explain:"La religion soude le groupe."}]},{id:"philo-religion-vf",type:"vraifaux",title:"Vrai / Faux — La religion",icon:"⚡",questions:[{statement:"Croire et savoir, c’est exactement la même chose.",answer:!1,explain:"Faux : l’un est sans preuve, l’autre avec preuve."},{statement:"Pour Pascal, la foi peut dépasser la raison.",answer:!0,explain:"Vrai : « le cœur a ses raisons »."},{statement:"Durkheim voit dans la religion un lien social.",answer:!0,explain:"Vrai : elle soude le groupe."}]}]},{id:"philo-technique",name:"La technique",short:"La technique",keywords:"technique outil travail homo faber Bergson Heidegger Jonas Rousseau progrès moyen fin smartphone",intro:"Le smartphone nous libère (tout savoir, partout) et nous asservit (dépendance, surveillance). Une seule technique, deux visages : nous libère-t-elle ou nous asservit-elle ?",cours:[{h:"🔧 Comprendre — la technique par l’exemple (le smartphone)",blocks:[{t:"example",h:"Situation",c:"Le smartphone nous libère (accès à tout, joindre n’importe qui) et nous asservit (notifications, dépendance, surveillance des données)."},{t:"list",c:["**Définir** : la technique est l’ensemble des **procédés efficaces** par lesquels l’homme transforme la nature pour produire de l’**utile** (≠ l’art qui vise le beau, ≠ la science qui vise le vrai).","L’homme est *homo faber*, l’animal qui **fabrique des outils** (**Bergson**).","**La distinction clé** : *moyen / fin*. La technique est un **moyen** ; la question est **ce que nous en faisons**."]},{t:"tip",h:"Réflexe",c:"La technique n’est ni bonne ni mauvaise en soi : interroge toujours son **usage** et sa **maîtrise**."}]},{h:"🤔 Le problème — nous libère-t-elle ou nous asservit-elle ?",blocks:[{t:"list",c:["**Thèse 1 — elle libère** : elle nous affranchit des contraintes naturelles (médecine, transports, moins de pénibilité).","**Thèse 2 — elle asservit** : **Heidegger** : la technique moderne traite la nature (et l’homme) comme un simple **stock exploitable** ; **Jonas** alerte sur des risques inédits (nucléaire, climat).","**Progrès technique = progrès moral ?** **Rousseau** en doute : les sciences et les arts n’ont pas rendu les hommes meilleurs."]},{t:"tip",h:"Citation utile",c:"« Maîtres et possesseurs de la nature » (Descartes) — l’ambition d’une technique qui libère."}]},{h:"🎓 Approfondir & au bac",blocks:[{t:"list",c:["**Moyen / fin** : un même outil (le couteau) **soigne ou tue** ; tout dépend de la fin poursuivie.","**Piège** : croire que le progrès technique entraîne **automatiquement** le progrès humain."]},{t:"example",h:"Sujet type",c:"« La technique nous libère-t-elle ? » → I. Elle nous libère de la nature — II. Mais elle crée de nouvelles dépendances (Heidegger, Jonas) — III. Tout dépend de l’usage : rester maître de nos moyens."},{t:"tip",h:"Repères mobilisables",c:"Moyen / fin · cause / fin · en théorie / en pratique."}]}],essentiel:["Définir : la technique = procédés efficaces pour transformer la nature ; l’homme est *homo faber* (**Bergson**).","Deux visages : elle **libère** de la nature / elle peut **asservir** (**Heidegger**, **Jonas**).","Distinction **moyen / fin** : tout dépend de l’**usage** ; progrès technique ≠ progrès moral (**Rousseau**)."],resources:[{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Cherche « la technique », « progrès »."},{label:"Lumni — Philosophie",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « la technique », « le travail »."}],games:[{id:"philo-technique-flash",type:"flashcard",title:"Flashcards — La technique",icon:"🃏",cards:[{front:"Technique",back:"Procédés efficaces pour transformer la nature et produire de l’utile."},{front:"Homo faber (Bergson)",back:"L’homme, animal qui fabrique des outils."},{front:"Heidegger",back:"La technique moderne traite tout comme un stock exploitable."},{front:"Jonas",back:"La puissance technique crée des risques inédits → responsabilité."},{front:"Moyen / fin",back:"La technique est un moyen : tout dépend de l’usage (le couteau soigne ou tue)."}]},{id:"philo-technique-assoc",type:"association",title:"Association — Technique",icon:"🔗",pairs:[{left:"Bergson",right:"Homo faber"},{left:"Heidegger",right:"La nature comme stock exploitable"},{left:"Jonas",right:"Responsabilité face aux risques"},{left:"Rousseau",right:"Le progrès ne rend pas meilleur"}]},{id:"philo-technique-qcm",type:"qcm",title:"QCM — La technique",icon:"❓",questions:[{q:"La technique se définit d’abord comme…",choices:["des procédés efficaces pour transformer la nature","la recherche du beau","la recherche du vrai","une croyance"],answer:0,explain:"Elle vise l’utile (≠ art, ≠ science)."},{q:"« Homo faber » (l’homme qui fabrique des outils) vient de…",choices:["Bergson","Platon","Marx","Kant"],answer:0,explain:"Bergson caractérise l’intelligence par l’outil."},{q:"La distinction utile pour juger la technique est…",choices:["moyen / fin","beau / laid","légal / légitime","inné / acquis"],answer:0,explain:"La technique est un moyen : tout dépend de la fin."},{q:"Que la technique nous asservisse est défendu notamment par…",choices:["Heidegger et Jonas","Aristote seul","Kant","personne"],answer:0,explain:"Ils alertent sur l’exploitation et les risques."}]},{id:"philo-technique-vf",type:"vraifaux",title:"Vrai / Faux — La technique",icon:"⚡",questions:[{statement:"La technique est bonne ou mauvaise en elle-même.",answer:!1,explain:"Faux : tout dépend de l’usage (moyen / fin)."},{statement:"Le progrès technique entraîne automatiquement le progrès moral.",answer:!1,explain:"Faux : Rousseau en doute."},{statement:"La technique peut nous libérer des contraintes naturelles.",answer:!0,explain:"Vrai : médecine, transports…"}]}]},{id:"philo-verite",name:"La vérité",short:"La vérité",keywords:"vérité réalité opinion savoir démontrer doute Descartes Platon Leibniz caverne cogito",intro:"« La Terre est plate » fut longtemps une opinion répandue. Mais une vérité ne se décide pas à la majorité : elle se démontre ou se vérifie. Qu’est-ce donc que la vérité ?",cours:[{h:"🔍 Comprendre — la vérité par l’exemple (« la Terre est plate »)",blocks:[{t:"example",h:"Situation",c:"« La Terre est plate » fut longtemps une opinion partagée. Mais une vérité ne se décide pas au vote : elle se **démontre** ou se **vérifie**."},{t:"list",c:["**Définir** : la vérité est l’**accord de la pensée avec son objet** (adéquation).","**Vérité / réalité** : la réalité est ce qui **est** ; la vérité est une propriété de nos **jugements** sur le réel.","**Opinion / savoir** : l’**opinion** (*doxa*) est une croyance non fondée ; le **savoir** est justifié."]},{t:"tip",h:"Réflexe",c:"Distingue « c’est mon avis » (opinion) et « c’est démontré/vérifié » (savoir)."}]},{h:"🤔 Le problème — peut-on tout démontrer ?",blocks:[{t:"list",c:["**Sortir de l’opinion** : **Platon** — l’allégorie de la **caverne** : passer des **ombres** (les apparences) à la **lumière** (les Idées, le vrai).","**Les limites de la démonstration** : toute démonstration part d’**axiomes** indémontrables ; **Leibniz** distingue **vérités de raison** (logiques) et **vérités de fait** (vérifiées par l’expérience).","**Le rôle du doute** : **Descartes** doute volontairement de tout (**doute méthodique**) pour trouver une première certitude : « je pense, donc je suis »."]},{t:"tip",h:"Citation utile",c:"« Je pense, donc je suis. » (Descartes) — la première vérité que le doute ne peut emporter."}]},{h:"🎓 Approfondir & au bac",blocks:[{t:"list",c:["**Opinion / savoir** est le repère central : une vérité ne dépend pas du nombre de gens qui y croient.","**Piège** : « à chacun sa vérité » confond **goût** (subjectif) et **vérité** (qui prétend valoir pour tous)."]},{t:"example",h:"Sujet type",c:"« Toutes les opinions se valent-elles ? » → I. Chacun a droit à son opinion — II. Mais l’opinion n’est pas le savoir (Platon) — III. La vérité se démontre ou se vérifie : toutes ne se valent pas."},{t:"tip",h:"Repères mobilisables",c:"Objectif / subjectif · croire / savoir · démontrer / prouver."}]}],essentiel:["Définir : vérité = **accord de la pensée avec son objet** ; à distinguer de la **réalité**.","**Platon** (caverne) : sortir de l’**opinion** vers le **savoir** ; **Descartes** : doute méthodique → « je pense, donc je suis ».","**Leibniz** : vérités de raison / vérités de fait ; on ne peut pas **tout** démontrer."],resources:[{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Cherche « la vérité », « le doute »."},{label:"Lumni — Philosophie",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « la vérité », « l’allégorie de la caverne »."}],games:[{id:"philo-verite-flash",type:"flashcard",title:"Flashcards — La vérité",icon:"🃏",cards:[{front:"Vérité",back:"Accord de la pensée avec son objet (adéquation)."},{front:"Vérité / réalité",back:"La réalité est ce qui est ; la vérité qualifie nos jugements."},{front:"Opinion / savoir",back:"Croyance non fondée (doxa) / connaissance justifiée."},{front:"Platon (caverne)",back:"Passer des ombres (apparences) à la lumière (le vrai)."},{front:"Descartes",back:"Doute méthodique → « je pense, donc je suis »."}]},{id:"philo-verite-assoc",type:"association",title:"Association — Vérité",icon:"🔗",pairs:[{left:"Platon",right:"Allégorie de la caverne"},{left:"Descartes",right:"Doute méthodique / cogito"},{left:"Leibniz",right:"Vérités de raison / de fait"},{left:"Opinion",right:"Croyance non fondée (doxa)"}]},{id:"philo-verite-qcm",type:"qcm",title:"QCM — La vérité",icon:"❓",questions:[{q:"La vérité se définit comme…",choices:["l’accord de la pensée avec son objet","ce qui plaît au plus grand nombre","une simple opinion","ce qui est utile"],answer:0,explain:"Définition classique par adéquation."},{q:"L’allégorie de la caverne est de…",choices:["Platon","Descartes","Leibniz","Kant"],answer:0,explain:"Sortir des ombres vers la lumière du vrai."},{q:"« Je pense, donc je suis » vient de…",choices:["Descartes","Platon","Pascal","Sartre"],answer:0,explain:"La première certitude après le doute méthodique."},{q:"Peut-on tout démontrer ?",choices:["Non : toute démonstration part d’axiomes indémontrables","Oui, toujours","Seulement en histoire","Cela ne veut rien dire"],answer:0,explain:"Leibniz : vérités de raison / vérités de fait."}]},{id:"philo-verite-vf",type:"vraifaux",title:"Vrai / Faux — La vérité",icon:"⚡",questions:[{statement:"Une vérité dépend du nombre de gens qui y croient.",answer:!1,explain:"Faux : elle se démontre ou se vérifie."},{statement:"Le doute, chez Descartes, sert à atteindre une certitude.",answer:!0,explain:"Vrai : doute méthodique → cogito."},{statement:"Opinion et savoir sont synonymes.",answer:!1,explain:"Faux : l’opinion n’est pas justifiée, le savoir l’est."}]}]},{id:"philo-methode",name:"Méthode & auteurs",short:"Méthode",keywords:"dissertation explication de texte problématiser thèse antithèse dépassement auteurs citations Platon Descartes Kant Sartre",intro:"Au bac, on choisit entre une dissertation et une explication de texte. Dans les deux cas, la note récompense la méthode et l’argumentation, pas la récitation. Voici comment structurer un devoir — et les auteurs à mobiliser.",cours:[{h:"✍️ La dissertation, étape par étape",blocks:[{t:"p",c:"La dissertation répond à **une question** par une argumentation **progressive**. On ne récite pas le cours : on **s’en sert** pour raisonner."},{t:"table",head:["Étape","Ce qu’on fait"],rows:[["1. Analyser","Décortiquer le sujet, **définir** chaque terme important"],["2. Problématiser","Dégager le **paradoxe**, le vrai problème (la tension entre deux réponses)"],["3. Plan","Construire un plan **progressif** (souvent thèse → antithèse → dépassement)"],["4. Argumenter","Chaque partie = une idée + un **argument** + un **exemple** ou un **auteur**"],["5. Conclure","Répondre **clairement** au problème, ouvrir sur une nouvelle question"]]},{t:"example",h:"Introduction rédigée — « La technique nous libère-t-elle ? »",c:"Chaque jour, le GPS ou la machine à laver nous épargnent mille efforts : la technique paraît libératrice. Pourtant, beaucoup se sentent esclaves de leurs écrans. La technique désigne les procédés efficaces par lesquels l’homme transforme la nature ; libérer, c’est affranchir d’une contrainte. Le problème : si la technique nous délivre des contraintes naturelles, ne crée-t-elle pas de nouvelles dépendances ? Nous verrons qu’elle libère de la nature, puis qu’elle peut asservir, enfin que tout dépend de l’usage."},{t:"warning",c:"Les deux pièges qui plombent une copie : le **hors-sujet** (on n’a pas analysé le sujet) et la **récitation** (on déroule le cours sans problématiser). Reviens sans cesse à **la** question posée."}]},{h:"📖 L’explication de texte — l’exemple du « roseau pensant »",blocks:[{t:"example",h:"Le texte",c:"« L’homme n’est qu’un roseau, le plus faible de la nature ; mais c’est un roseau pensant. » (Pascal, Pensées)"},{t:"list",c:["**① Dégager la thèse** : la grandeur de l’homme ne tient pas à sa force, mais à sa **pensée**.","**② Suivre les mouvements** : (a) « le plus faible de la nature » = la fragilité physique ; (b) le « **mais** » renverse tout : « roseau **pensant** » = la pensée fait sa dignité.","**③ Expliquer** : Pascal oppose la faiblesse du **corps** à la puissance de l’**esprit** ; l’homme est supérieur à l’univers car il **le sait**.","**④ Discuter** : où placer la dignité humaine ? Dans la conscience plutôt que dans la force."]},{t:"tip",h:"Réflexe",c:"Repère les mots de liaison (« mais », « donc », « car ») : ils marquent les mouvements et la logique du texte."}]},{h:"👤 Les auteurs & les citations à mobiliser",blocks:[{t:"table",head:["Auteur","Idée clé","Notions"],rows:[["Platon","Allégorie de la caverne : des apparences à la vérité","Vérité, art"],["Aristote","Justice distributive et corrective, l’équité qui corrige la loi ; l’homme « animal politique »","Justice"],["Descartes","Doute méthodique, cogito, maîtrise de la nature","Vérité, technique"],["Pascal","Le « roseau pensant » ; les raisons du cœur","Religion, nature"],["Rousseau","Nature / culture ; le contrat social","Justice, liberté"],["Kant","L’autonomie ; le jugement de goût","Liberté, art"],["Sartre","L’existence précède l’essence : liberté-responsabilité","Liberté"]]},{t:"tip",h:"Stratégie",c:"Mieux vaut **quelques auteurs bien maîtrisés** (une idée, un exemple chacun) que dix noms récités."}]}],essentiel:["**Dissertation** : analyser → problématiser → plan progressif (thèse / antithèse / dépassement) → argumenter → conclure.","**Explication de texte** : dégager la **thèse**, suivre les **mouvements**, expliquer, puis discuter.","Deux pièges : le **hors-sujet** et la **récitation**. On mobilise **quelques auteurs** bien maîtrisés."],resources:[{label:"Éduscol — programme & sujets de philosophie (voie techno)",url:"https://eduscol.education.fr/",kind:"doc",note:"Le programme officiel et des exemples de sujets."},{label:"France Culture — « Les chemins de la philosophie »",url:"https://www.radiofrance.fr/franceculture/podcasts/les-chemins-de-la-philosophie",kind:"link",note:"Pour nourrir ses exemples et ses auteurs."},{label:"Lumni — méthode de la dissertation et du texte",url:"https://www.lumni.fr/",kind:"video",note:"Cherche « dissertation philosophie », « explication de texte »."}],games:[{id:"philo-methode-ordre",type:"ordre",title:"Remise en ordre — La dissertation",icon:"🔢",instruction:"Remets les étapes de la dissertation dans l’ordre.",steps:["Analyser le sujet","Définir les termes","Problématiser (dégager le paradoxe)","Construire un plan progressif","Argumenter (idée + argument + exemple/auteur)","Conclure"],explain:"On analyse, on définit, on problématise, on planifie, on argumente, puis on conclut."},{id:"philo-methode-ordre2",type:"ordre",title:"Remise en ordre — L’explication de texte",icon:"🔢",instruction:"Remets les étapes de l’explication de texte dans l’ordre.",steps:["Dégager la thèse du texte","Repérer les mouvements (parties)","Expliquer le raisonnement de l’auteur","Éclairer les mots et les exemples","Discuter la portée et les enjeux"],explain:"Thèse → mouvements → explication → éclairage → discussion."},{id:"philo-methode-tri",type:"tri",title:"Tri — Auteurs par période",icon:"🗂️",instruction:"Classe chaque auteur dans sa période.",categories:[{id:"ant",label:"Antiquité / Moyen Âge"},{id:"mod",label:"Moderne"},{id:"con",label:"Contemporaine"}],items:[{text:"Platon",cat:"ant"},{text:"Aristote",cat:"ant"},{text:"Descartes",cat:"mod"},{text:"Kant",cat:"mod"},{text:"Sartre",cat:"con"},{text:"Arendt",cat:"con"}]},{id:"philo-methode-auteurs",type:"association",title:"Association — Auteur ↔ idée clé",icon:"🔗",pairs:[{left:"Platon",right:"Allégorie de la caverne"},{left:"Descartes",right:"Doute méthodique / cogito"},{left:"Rousseau",right:"Nature / culture ; contrat social"},{left:"Kant",right:"Autonomie ; jugement de goût"},{left:"Sartre",right:"L’existence précède l’essence"}]},{id:"philo-methode-cit",type:"flashcard",title:"Flashcards — Citations essentielles",icon:"🃏",cards:[{front:"« L’homme est condamné à être libre. »",back:"Sartre — la liberté et la responsabilité."},{front:"« Je pense, donc je suis. »",back:"Descartes — la vérité et le cogito."},{front:"« Maîtres et possesseurs de la nature. »",back:"Descartes — la technique et la nature."},{front:"« Le cœur a ses raisons… »",back:"Pascal — la religion, foi et raison."},{front:"« L’art ne reproduit pas le visible, il rend visible. »",back:"Klee — l’art révèle."}]},{id:"philo-methode-qcm",type:"qcm",title:"QCM — Méthode & auteurs",icon:"❓",questions:[{q:"Le cœur de l’introduction d’une dissertation, c’est…",choices:["problématiser (dégager le paradoxe)","donner la conclusion","réciter le cours","citer dix auteurs"],answer:0,explain:"Après avoir défini les termes, on problématise."},{q:"Un plan classique de dissertation est…",choices:["thèse / antithèse / dépassement","intro / développement seulement","liste de définitions","résumé du texte"],answer:0,explain:"Plan progressif dialectique."},{q:"Pour l’explication de texte, on commence par…",choices:["dégager la thèse du texte","donner son avis personnel","compter les lignes","résumer le programme"],answer:0,explain:"On suit d’abord la pensée de l’auteur."},{q:"Descartes appartient à la période…",choices:["moderne","antique","contemporaine","médiévale"],answer:0,explain:"Avec Pascal, Rousseau, Kant."},{q:"Le « dépassement » (3ᵉ partie) consiste à…",choices:["résoudre la tension par une idée plus juste","répéter la thèse","abandonner le sujet","donner un avis sans argument"],answer:0,explain:"Il articule thèse et antithèse."}]},{id:"philo-methode-vf",type:"vraifaux",title:"Vrai / Faux — Méthode",icon:"⚡",questions:[{statement:"La dissertation consiste à réciter le cours.",answer:!1,explain:"Faux : elle argumente pour répondre à un problème."},{statement:"Le hors-sujet et la récitation sont deux pièges majeurs.",answer:!0,explain:"Vrai : reviens toujours à la question posée."},{statement:"Il faut citer le plus d’auteurs possible.",answer:!1,explain:"Faux : quelques auteurs bien maîtrisés suffisent."}]}]}],c={id:e,name:i,short:t,icon:s,color:n,tagline:r,chapters:a},b=Object.freeze(Object.defineProperty({__proto__:null,chapters:a,color:n,default:c,icon:s,id:e,name:i,short:t,tagline:r},Symbol.toStringTag,{value:"Module"})),p={"philo-art":[{h:"🔎 Définitions & distinctions approfondies",blocks:[{t:"p",c:"Avant toute dissertation sur l’art, il faut maîtriser un réseau de distinctions. La première oppose le **beau** et l’**agréable** : l’agréable dépend de ma sensibilité (un plat, une température) et n’engage que moi ; le beau, lui, **prétend** valoir pour autrui — quand je dis « ce tableau est beau », j’attends que tu partages mon jugement. C’est le paradoxe kantien : un jugement **subjectif** (il ne repose sur aucun concept, aucune règle) mais qui vise l’**universel**."},{t:"p",c:"La deuxième distinction sépare l’**art** de la **technique** (et de l’artisanat). L’artisan produit un objet **utile** en suivant un modèle reproductible ; l’artiste crée une œuvre **unique** dont la fin est en elle-même. Une troisième distinction, plus subtile, oppose le **beau** au **sublime** : le beau apaise et plaît par sa forme harmonieuse ; le sublime (une tempête, la haute montagne, l’immensité du ciel) nous dépasse, mêle plaisir et effroi, et révèle en nous une grandeur morale — c’est la thèse de Kant dans la *Critique de la faculté de juger*."},{t:"table",head:["Distinction","Un côté","L’autre côté"],rows:[["Beau / agréable","Prétend valoir pour tous","Ne vaut que pour moi"],["Art / artisanat","Œuvre singulière, fin en soi","Objet utile, reproductible"],["Beau / sublime","Harmonie, plaisir paisible","Démesure, plaisir mêlé d’effroi"],["Imiter / créer","Reproduire le réel","Révéler, transfigurer"]]},{t:"tip",h:"Au bac",c:"Ouvrir une copie sur une **distinction précise** (beau/agréable, art/technique) montre immédiatement que l’on ne confond pas les termes du sujet."}]},{h:"⚔️ Les grandes thèses en débat",blocks:[{t:"p",c:"**Thèse 1 — l’art imite (et il faut s’en méfier).** Pour **Platon** (*La République*, livre X), l’artiste ne fait que copier les apparences sensibles, elles-mêmes copies des Idées : l’art est donc à la troisième place, éloigné du vrai, et dangereux car il flatte la partie irrationnelle de l’âme. Le poète est banni de la cité idéale."},{t:"p",c:"**Thèse 2 — l’art imite pour instruire et purifier.** **Aristote** (*Poétique*) réhabilite l’imitation : l’homme apprend d’abord en imitant, et la tragédie, en représentant la pitié et la terreur, produit une **catharsis**, une purgation bienfaisante des passions. L’art n’éloigne pas du réel, il en révèle le sens universel."},{t:"p",c:"**Thèse 3 — l’art manifeste une vérité spirituelle.** Pour **Hegel**, l’art est un moment par lequel l’Esprit se donne une forme sensible : il ne copie pas, il **exprime** l’intériorité, l’époque, l’humain. **Thèse 4 — l’art est pur jeu de la forme et du génie.** Le romantisme (Baudelaire, la théorie de « l’art pour l’art ») affirme l’autonomie de l’œuvre : elle ne doit être ni utile, ni morale, ni imitative — seulement belle."},{t:"warning",h:"Piège",c:"Ne pas réduire le débat à « l’art copie / l’art ne copie pas ». La vraie question est : **que fait** l’œuvre ? Plaît-elle, instruit-elle, révèle-t-elle, dérange-t-elle ?"}]},{h:"📜 Textes clés commentés",blocks:[{t:"example",h:"Texte 1 — Platon, la condamnation de l’imitation",c:"« L’imitateur est bien loin du vrai. » Platon range le peintre après le menuisier (qui fabrique un vrai lit) et après le dieu (qui crée l’Idée de lit)."},{t:"p",c:"**Commentaire.** Platon hiérarchise trois niveaux : l’Idée (le vrai lit intelligible), l’objet fabriqué (le lit sensible), l’image peinte (la copie de l’objet). L’art, doublement éloigné, ne produit que des **apparences d’apparences**. L’enjeu est moral et politique : une cité juste doit se méfier de ce qui charme sans instruire."},{t:"example",h:"Texte 2 — Klee, l’art qui rend visible",c:"« L’art ne reproduit pas le visible, il rend visible. » (Paul Klee)"},{t:"p",c:"**Commentaire.** Renversement complet de Platon : l’art ne vaut pas parce qu’il ressemble, mais parce qu’il **fait apparaître** ce que l’œil ordinaire ne perçoit pas — une émotion, une structure, une vérité cachée. *Guernica* ne « ressemble » pas à un bombardement : il en rend visible l’horreur."},{t:"tip",h:"Méthode",c:"Un texte se commente en 3 temps : la **thèse**, les **mouvements** (le « donc », le « mais »), les **enjeux**. Toujours relier au reste du programme."}]},{h:"🌍 Prolongements — l’art aujourd’hui",blocks:[{t:"p",c:"Les questions classiques se rejouent à l’ère contemporaine. La **reproductibilité technique** (Walter Benjamin) : une photo, un film, un fichier numérique existent en d’innombrables copies — l’œuvre perd son « aura », son ici-et-maintenant unique. Cela change-t-il sa valeur ? Le **marché de l’art** : quand une œuvre se vend des millions, est-ce sa beauté ou sa cote financière que l’on achète ? L’**art numérique** et l’**IA générative** relancent la question de la création : une image produite par une machine est-elle une œuvre, et qui en est l’auteur ?"},{t:"p",c:"Ces débats ne sont pas nouveaux : ils prolongent Duchamp (qu’est-ce qui fait qu’une chose est de l’art ?) et Platon (l’image nous éloigne-t-elle du réel ?). Savoir les rattacher aux notions classiques est très valorisé."},{t:"tip",h:"Exemple mobilisable",c:"Le *ready-made* (l’objet ordinaire promu œuvre) est l’exemple parfait pour discuter la définition de l’art : c’est le regard et l’institution, non l’objet, qui font l’œuvre."}]},{h:"✍️ Deuxième dissertation guidée — « L’art nous détourne-t-il de la réalité ? »",blocks:[{t:"p",c:"**Analyse & problématique.** « Détourner » suppose que l’art nous éloignerait du réel, comme une évasion ou une illusion. Mais l’art ne nous fait-il pas, au contraire, mieux **voir** le réel ? Le problème : l’art est-il fuite du réel ou dévoilement du réel ?"},{t:"list",c:["**I. Oui, l’art peut détourner du réel.** Il produit des illusions (Platon), offre une évasion, un divertissement (Pascal), voire une consolation qui endort — l’art « décoratif » qui masque la laideur du monde.","**II. Mais l’art révèle le réel autrement.** Il rend visible l’invisible (Klee), dit une vérité sur l’homme (Hegel), dénonce (Guernica, la littérature engagée). Loin de fuir, il **intensifie** notre présence au monde (Proust).","**III. Dépassement.** L’art nous « détourne » du réel utilitaire et quotidien, non pour nous en éloigner, mais pour nous le faire **redécouvrir** avec un regard neuf. Il suspend l’habitude et l’intérêt — c’est ce détour qui nous rend au réel."]},{t:"example",h:"Conclusion",c:"L’art nous détourne du réel banal pour mieux nous en rapprocher : son « inutilité » est une manière supérieure de nous rendre au monde et à nous-mêmes."}]}],"philo-justice":[{h:"🔎 Définitions & distinctions approfondies",blocks:[{t:"p",c:"La justice se dit en plusieurs sens qu’il faut soigneusement distinguer. Comme **vertu**, elle est la disposition à rendre à chacun son dû (Aristote). Comme **institution**, elle est l’appareil qui tranche les litiges (les tribunaux). Comme **idéal**, elle est ce vers quoi tend le droit : l’équité. Confondre ces sens conduit à des contresens (« la justice a condamné X » ne dit rien de la justice de la décision)."},{t:"p",c:"La distinction reine est celle du **légal** et du **légitime** : est légal ce qui est conforme à la loi positive en vigueur ; est légitime ce qui est conforme à la justice, à ce qui **devrait** être le droit. Tout l’espace de la critique politique tient dans cet écart. S’ajoute la distinction du **droit** (les règles) et du **fait** (la force) : « la force fait-elle le droit ? » — non, répond Rousseau, sinon « le plus fort » n’aurait jamais qu’une puissance, jamais une autorité légitime."},{t:"table",head:["Distinction","Sens","Exemple"],rows:[["Légal / légitime","Conforme à la loi / à la justice","Une loi injuste est légale mais illégitime"],["Égalité / équité","La même chose pour tous / adapter au cas","Même impôt vs impôt proportionnel"],["Droit / fait","Ce qui doit être / ce qui est (la force)","Le vol réussit (fait) mais reste injuste (droit)"],["Justice commutative / distributive","Échanges égaux / répartition selon le mérite","Un contrat équitable / une récompense méritée"]]},{t:"tip",h:"À retenir",c:"L’**équité** (Aristote) corrige la loi générale quand son application mécanique produirait, dans un cas particulier, une injustice."}]},{h:"⚔️ Les grandes thèses — de quoi la justice est-elle faite ?",blocks:[{t:"p",c:"**Thèse cynique (Calliclès, Thrasymaque).** La justice n’est qu’un mot : dans les faits, règne la loi du plus fort ; les lois sont faites par les puissants pour servir leurs intérêts. C’est la thèse que toute la philosophie va combattre."},{t:"p",c:"**Thèse du contrat (Hobbes, Rousseau).** La justice naît d’un **pacte** : pour sortir de la violence de l’état de nature, les hommes conviennent de règles communes. Chez Hobbes, ils se soumettent à un souverain absolu par peur de la mort ; chez Rousseau, ils forment une « volonté générale » et n’obéissent qu’à eux-mêmes — d’où une justice qui **fonde** la liberté au lieu de la supprimer."},{t:"p",c:"**Thèse de l’équité (Rawls).** Derrière un « voile d’ignorance » (j’ignore quelle sera ma place dans la société), quelles règles choisir ? Rawls soutient qu’on choisirait des institutions qui garantissent à tous des libertés de base **et** qui n’admettent d’inégalités que si elles profitent aux plus défavorisés. La justice devient « équité »."},{t:"warning",h:"Piège fréquent",c:"Confondre **égalité** et **justice**. Traiter identiquement des situations inégales peut être **injuste** : la justice exige parfois l’inégalité (proportionnalité, équité)."}]},{h:"📜 Textes & cas commentés",blocks:[{t:"example",h:"Rousseau — le droit du plus fort",c:"« Le plus fort n’est jamais assez fort pour être toujours le maître, s’il ne transforme sa force en droit et l’obéissance en devoir. » (*Du contrat social*, I, 3)"},{t:"p",c:"**Commentaire.** La force peut contraindre (je cède au voleur armé), mais elle n’**oblige** pas moralement : dès qu’elle faiblit, l’obéissance cesse. Une autorité durable a besoin de **légitimité**, non de simple puissance. Rousseau démonte ainsi l’idée que « la force fait le droit »."},{t:"example",h:"Cas — Rosa Parks (1955)",c:"En refusant de céder sa place dans le bus, Rosa Parks enfreint une loi **légale** (la ségrégation) au nom d’une justice **légitime**."},{t:"p",c:"**Commentaire.** Ce cas illustre la **désobéissance civile** : enfreindre publiquement une loi injuste, sans violence, en acceptant la sanction, pour en appeler à une loi meilleure. Ce n’est pas de l’anarchie (on respecte l’idée de loi), mais un acte politique au nom de la justice."}]},{h:"🌍 Prolongements — justice sociale et mondiale",blocks:[{t:"p",c:"Les débats contemporains prolongent ces questions. La **justice sociale** interroge la répartition des richesses (Rawls, Amartya Sen et les « capabilités »). La **justice pénale** oppose des finalités : punir pour **rétribuer** (rendre le mal pour le mal), pour **dissuader**, ou pour **réinsérer** ? La **justice mondiale** pose la question des inégalités entre pays et de la responsabilité envers les générations futures."},{t:"p",c:"La pensée d’**Hannah Arendt** est ici précieuse : jugeant Eichmann, elle forge l’idée de « **banalité du mal** » — le fonctionnaire qui obéit aux ordres sans penser. Obéir à la loi ne suffit donc pas : la justice exige de **penser** par soi-même ce que l’on fait."},{t:"tip",h:"Ouverture",c:"Relier justice et liberté : sans justice, la liberté du plus fort écrase celle des autres ; la loi juste est la condition de la liberté de tous."}]},{h:"✍️ Deuxième dissertation guidée — « La justice se réduit-elle au respect des lois ? »",blocks:[{t:"list",c:["**I. Oui, être juste, c’est respecter les lois.** La loi, égale pour tous, arrache à l’arbitraire ; sans respect des lois, chacun se fait juge et c’est le chaos (Hobbes). Le juste semble donc coïncider avec le légal.","**II. Mais une loi peut être injuste.** Légal ≠ légitime : l’histoire regorge de lois iniques. Réduire la justice au respect des lois interdirait de les critiquer — et rendrait complice (Arendt).","**III. Dépassement.** La justice est l’**idéal** au nom duquel on juge et, au besoin, on réforme les lois. Respecter les lois est nécessaire, mais la justice les **dépasse** : elle est ce qui donne aux lois leur autorité — ou les condamne."]},{t:"example",h:"Conclusion",c:"Le respect des lois est la forme ordinaire de la justice, non son essence : c’est parce qu’il existe une idée de justice supérieure aux lois que l’on peut les vouloir plus justes."}]}],"philo-liberte":[{h:"🔎 Définitions & distinctions approfondies",blocks:[{t:"p",c:"La liberté se décline en plusieurs figures. La **liberté d’action** est l’absence d’obstacles extérieurs (je peux marcher, parler). La **liberté de la volonté** ou **libre arbitre** est le pouvoir de choisir entre plusieurs possibles. L’**autonomie** (du grec *autos*, soi-même, et *nomos*, loi) est le pouvoir de se donner à soi-même sa propre loi — figure supérieure, morale, de la liberté (Kant)."},{t:"p",c:"Il faut distinguer la liberté de la **licence** (faire n’importe quoi selon ses caprices) : suivre tous ses désirs, c’est souvent en être l’esclave. Il faut aussi distinguer **contrainte** (obstacle extérieur qui empêche) et **obligation** (devoir intérieur qui engage) : la loi juste n’est pas une contrainte mais une obligation qui garantit la liberté de tous. Enfin, le débat central oppose **liberté** et **déterminisme** (tout a une cause) : le déterminisme rend-il la liberté impossible ?"},{t:"table",head:["Distinction","Un côté","L’autre côté"],rows:[["Autonomie / licence","Se donner sa loi","Faire n’importe quoi"],["Contrainte / obligation","Obstacle extérieur","Devoir intérieur"],["Liberté / libre arbitre","Pouvoir agir","Pouvoir choisir"],["Libre / déterminé","Cause en soi","Effet de causes antérieures"]]},{t:"tip",h:"À retenir",c:"On peut être **déterminé** et pourtant **responsable** : reconnaître les causes qui nous poussent (éducation, désirs) n’efface pas notre pouvoir de délibérer et de choisir."}]},{h:"⚔️ Les grandes thèses — sommes-nous libres ?",blocks:[{t:"p",c:"**Thèse 1 — nous sommes évidemment libres (Descartes).** Le libre arbitre est une évidence intérieure, « la principale perfection de l’homme » ; je fais l’expérience directe de pouvoir dire oui ou non. **Thèse 2 — cette liberté est une illusion (Spinoza).** Nous nous croyons libres parce que nous avons conscience de nos désirs, mais nous **ignorons les causes** qui les produisent. La pierre lancée, si elle pensait, se croirait libre de tomber."},{t:"p",c:"**Thèse 3 — la liberté est morale (Kant).** La liberté n’est pas dans le monde des phénomènes (déterminé) mais dans l’ordre moral : être libre, c’est obéir à la loi que la raison se donne (l’autonomie), agir par devoir. **Thèse 4 — nous sommes condamnés à être libres (Sartre).** Sans nature humaine ni Dieu pour décider à notre place, « l’existence précède l’essence » : nous sommes ce que nous faisons de nous, et donc entièrement responsables — d’où l’angoisse et la tentation de la « mauvaise foi »."},{t:"warning",h:"Piège",c:"Confondre liberté et **toute-puissance**. Être libre n’est pas tout pouvoir (les stoïciens) : c’est bien user du pouvoir de choisir dont on dispose, y compris intérieurement."}]},{h:"📜 Textes clés commentés",blocks:[{t:"example",h:"Spinoza — l’illusion du libre arbitre",c:"« Les hommes se croient libres parce qu’ils ont conscience de leurs actions, et ignorent les causes qui les déterminent. » (*Éthique*)"},{t:"p",c:"**Commentaire.** Spinoza ne nie pas que nous choisissions : il nie que nos choix soient **sans cause**. La conscience du désir masque son origine. Être vraiment libre, pour lui, ce n’est pas échapper aux causes, mais les **comprendre** — la liberté est une connaissance."},{t:"example",h:"Sartre — la condamnation à la liberté",c:"« L’homme est condamné à être libre : condamné, parce qu’il ne s’est pas créé lui-même, et par ailleurs cependant libre, parce qu’une fois jeté dans le monde, il est responsable de tout ce qu’il fait. »"},{t:"p",c:"**Commentaire.** Le paradoxe (« condamné » à être « libre ») dit que la liberté n’est pas un privilège confortable mais une **charge** : nous ne pouvons pas ne pas choisir, et aucune excuse (nature, société) ne nous décharge de la responsabilité de nos actes."}]},{h:"🌍 Prolongements — liberté, société, neurosciences",blocks:[{t:"p",c:"La question de la liberté se rejoue aujourd’hui sur plusieurs fronts. Les **neurosciences** (expériences de Libet) semblent montrer que le cerveau « décide » avant que nous en ayons conscience : cela ruine-t-il le libre arbitre, ou montre-t-il seulement que la conscience arrive après ? Le **conditionnement social** (publicité, algorithmes, « économie de l’attention ») fabrique nos désirs : sommes-nous libres de vouloir ce qu’on nous a appris à désirer ?"},{t:"p",c:"La **liberté politique**, elle, se pense avec Montesquieu (« la liberté est le droit de faire tout ce que les lois permettent ») et Tocqueville (le risque d’un « despotisme doux » où le confort endort la vigilance des citoyens). Là encore : la vraie liberté suppose des lois et une conscience éveillée."},{t:"tip",h:"Exemple",c:"L’addiction (au tabac, aux écrans) est l’exemple parfait d’une liberté minée de l’intérieur : la conscience du choix n’en garantit pas la liberté."}]},{h:"✍️ Deuxième dissertation guidée — « Sommes-nous responsables de ce que nous sommes ? »",blocks:[{t:"list",c:["**I. Non : nous sommes le produit de causes.** Hérédité, éducation, milieu social, inconscient (Freud) : nous n’avons choisi ni notre naissance ni nos premiers déterminismes. Il semble injuste d’être tenu responsable de ce qu’on n’a pas choisi.","**II. Mais nous nous faisons par nos choix.** Sartre : au-delà de ce qui nous est donné, nous **décidons** de ce que nous en faisons ; se dire « déterminé » est souvent une excuse (mauvaise foi). La responsabilité est le prix de la liberté.","**III. Dépassement.** Nous ne sommes pas responsables de nos **conditions**, mais de ce que nous en faisons ; reconnaître nos déterminismes (les comprendre, à la manière de Spinoza) est même la condition pour commencer à s’en libérer."]},{t:"example",h:"Conclusion",c:"Nous ne choisissons pas notre point de départ, mais nous répondons de notre trajet : la responsabilité ne suppose pas une liberté absolue, seulement le pouvoir réel de délibérer et d’agir."}]}],"philo-nature":[{h:"🔎 Définitions & distinctions approfondies",blocks:[{t:"p",c:"Le mot « nature » est l’un des plus polysémiques de la langue philosophique. ① La **nature** peut désigner l’ensemble des êtres non produits par l’homme (l’environnement, le cosmos, le vivant). ② Elle peut désigner l’**essence** d’une chose, ce qui la fait être ce qu’elle est (« la nature humaine », « la nature du triangle »). ③ Elle peut enfin désigner l’**inné**, ce avec quoi l’on naît, par opposition à l’**acquis** (ce que l’on tient de l’éducation et de la culture)."},{t:"p",c:"La grande opposition anthropologique est **nature / culture**. La culture, c’est tout ce que l’homme ajoute à la nature : le langage, les techniques, les lois, les arts, les mœurs. Elle varie d’une société à l’autre (ce qui est « bien élevé » ici ne l’est pas ailleurs), tandis que la nature est universelle. Attention : beaucoup de comportements qu’on croit « naturels » (les rôles, les goûts) sont en réalité **culturels**, donc appris et modifiables."},{t:"table",head:["Sens de « nature »","S’oppose à","Exemple"],rows:[["L’environnement, le monde donné","L’artificiel, la technique","Une forêt / une autoroute"],["L’essence d’une chose","L’accidentel","« La nature de l’homme »"],["L’inné","L’acquis (la culture)","Un réflexe / une politesse apprise"]]},{t:"warning",h:"Sophisme naturaliste",c:"Passer du **fait** (« c’est naturel ») à la **valeur** (« c’est donc bien ») est une erreur logique. La nature décrit ce qui est, non ce qui doit être."}]},{h:"⚔️ Les grandes thèses — l’homme, la nature et la culture",blocks:[{t:"p",c:"**Thèse 1 — l’homme se distingue de la nature par la culture (Rousseau, Lévi-Strauss).** Ce qui définit l’humain, c’est la **perfectibilité** : la capacité de se transformer, d’apprendre, d’inventer. L’interdit de l’inceste, universel mais partout réglé différemment, marque le passage même de la nature à la culture (Lévi-Strauss)."},{t:"p",c:"**Thèse 2 — l’homme doit maîtriser la nature (Descartes).** La science a une visée pratique : nous rendre « comme maîtres et possesseurs de la nature », pour la santé et le bien-être. La nature est un domaine à connaître et à transformer. **Thèse 3 — l’homme doit respecter et protéger la nature (Jonas, écologie).** La démesure de notre puissance technique menace la biosphère : d’où un **principe responsabilité** envers le vivant et les générations futures."},{t:"p",c:"**Thèse 4 — l’homme est partie de la nature (Spinoza).** Se penser comme un « empire dans un empire », maître extérieur, est une illusion : l’homme est un mode de la Nature (*Deus sive Natura*), soumis à ses lois. Comprendre cela, c’est cesser de vouloir dominer pour apprendre à s’accorder."},{t:"tip",h:"Débat vivant",c:"Maîtrise (Descartes) contre responsabilité (Jonas) : c’est le cœur de tout sujet sur l’écologie."}]},{h:"📜 Textes & cas commentés",blocks:[{t:"example",h:"Descartes — maîtres et possesseurs de la nature",c:"« Nous rendre comme maîtres et possesseurs de la nature. » (*Discours de la méthode*, VI)"},{t:"p",c:"**Commentaire.** Le « comme » est capital : Descartes ne prône pas une domination orgueilleuse, mais une maîtrise **au service** de l’homme (« la conservation de la santé »). C’est le programme de la science moderne — qu’Hans Jonas, trois siècles plus tard, jugera à réviser au vu de ses conséquences."},{t:"example",h:"Cas — le barrage",c:"Un barrage produit une énergie « propre » mais noie une vallée et un écosystème."},{t:"p",c:"**Commentaire.** Le cas oblige à peser deux biens (l’énergie décarbonée, la préservation du vivant) : il n’y a pas de « nature » à préserver d’un côté et de « progrès » de l’autre, mais des **choix** à arbitrer avec responsabilité. La nature n’est ni un simple stock, ni un sanctuaire intouchable."}]},{h:"🌍 Prolongements — l’âge écologique",blocks:[{t:"p",c:"Notre époque a fait de la nature une question **politique et morale** urgente. L’« **anthropocène** » désigne l’ère où l’activité humaine est devenue une force géologique (climat, extinctions). La philosophie environnementale se divise : l’**écologie superficielle** protège la nature pour l’homme (ressources, cadre de vie) ; l’**écologie profonde** (Arne Næss) reconnaît une valeur au vivant **en soi**, indépendamment de son utilité."},{t:"p",c:"Le principe responsabilité de **Jonas** fournit une boussole : « agis de telle sorte que les effets de ton action soient compatibles avec la permanence d’une vie authentiquement humaine sur terre ». La nouveauté : notre responsabilité s’étend désormais à ceux qui **ne sont pas encore nés**."},{t:"tip",h:"Ouverture",c:"Relier nature et technique : c’est la puissance technique qui a rendu possible la domination — et la destruction — de la nature."}]},{h:"✍️ Deuxième dissertation guidée — « La culture dénature-t-elle l’homme ? »",blocks:[{t:"list",c:["**I. La culture éloigne l’homme de sa nature.** Rousseau : la société a corrompu l’homme, créé des besoins artificiels, des inégalités, de l’amour-propre. La culture serait un vernis qui masque et déforme la nature.","**II. Mais la culture est la nature même de l’homme.** Sans langage, sans techniques, sans éducation, il n’y a pas d’humanité : l’homme est par nature un être de culture. « Dénaturer » n’a alors pas de sens, puisque sa nature est de se cultiver.","**III. Dépassement.** La culture ne dénature pas l’homme : elle l’**accomplit** ou le **pervertit** selon l’usage. Le problème n’est pas la culture en soi, mais une culture qui trahit ce qu’il y a de meilleur dans l’humain."]},{t:"example",h:"Conclusion",c:"La culture ne s’oppose pas à la nature de l’homme : elle en est la réalisation. Reste à la vouloir digne de ce qu’elle prétend cultiver — l’humanité en l’homme."}]}],"philo-religion":[{h:"🔎 Définitions & distinctions approfondies",blocks:[{t:"p",c:"La religion articule des **croyances** (sur le sacré, le divin, l’au-delà) et des **pratiques** (rites, prières, fêtes) au sein d’une **communauté**. Étymologiquement, *religare* signifie relier (l’homme au divin, les hommes entre eux) et *relegere*, recueillir, observer scrupuleusement. Le cœur en est le **sacré** : ce qui est mis à part, entouré de respect et d’interdits, par opposition au **profane** (l’ordinaire)."},{t:"p",c:"La distinction philosophique décisive oppose **croire** et **savoir**. **Croire**, c’est tenir pour vrai **sans preuve** suffisante — soit par confiance (la foi religieuse), soit par simple opinion. **Savoir**, c’est tenir pour vrai **avec preuve** (démonstration, expérience vérifiable). La foi n’est donc pas un savoir raté : c’est un autre rapport à la vérité, qui engage la personne entière. À ne pas confondre non plus : la **foi** (adhésion vécue) et la **religion** (institution, dogme) ; on peut avoir l’une sans l’autre."},{t:"table",head:["Distinction","Un côté","L’autre côté"],rows:[["Croire / savoir","Sans preuve (foi, opinion)","Avec preuve (science)"],["Sacré / profane","Mis à part, objet de respect","Ordinaire, usuel"],["Foi / religion","Adhésion personnelle","Institution, dogme, rite"],["Croyance / superstition","Adhésion réfléchie","Crainte irrationnelle"]]},{t:"tip",h:"À retenir",c:"La **laïcité** n’est pas l’athéisme : c’est la neutralité de l’État, qui garantit à chacun la liberté de croire ou de ne pas croire."}]},{h:"⚔️ Les grandes thèses — foi, raison et critique",blocks:[{t:"p",c:"**Thèse 1 — la foi dépasse la raison sans la nier (Pascal).** « Le cœur a ses raisons que la raison ne connaît point » : il existe un ordre du cœur, une évidence intérieure, que la démonstration ne peut ni fonder ni détruire. Le **pari** de Pascal invite même le sceptique à parier sur Dieu, l’enjeu infini valant le risque fini."},{t:"p",c:"**Thèse 2 — la religion est une illusion utile (critique moderne).** **Marx** : « l’opium du peuple », une consolation qui apaise la souffrance des opprimés mais les détourne de changer leur condition réelle. **Freud** : une **illusion**, la projection d’un désir infantile de protection paternelle. **Nietzsche** : une morale du ressentiment qui invente des « arrière-mondes » pour dévaloriser la vie terrestre."},{t:"p",c:"**Thèse 3 — la religion est un fait social (Durkheim).** Indépendamment de la question de sa vérité, la religion remplit une fonction : elle **soude** le groupe, crée du lien, de l’identité, du rituel partagé. Le sacré, c’est la société qui se vénère elle-même sans le savoir."},{t:"warning",h:"Piège",c:"Traiter la religion comme une « science fausse ». Croire et savoir ne jouent pas sur le même terrain : la foi ne prétend pas démontrer, elle engage une confiance."}]},{h:"📜 Textes & cas commentés",blocks:[{t:"example",h:"Pascal — les deux ordres",c:"« Le cœur a ses raisons que la raison ne connaît point. » (*Pensées*)"},{t:"p",c:"**Commentaire.** Pascal ne dénigre pas la raison : il distingue **deux ordres** de connaissance. Le cœur (l’intuition, la foi) saisit des vérités que la raison démonstrative ne peut atteindre. La foi n’est donc pas déraisonnable : elle est d’un autre ordre que la démonstration."},{t:"example",h:"Cas — Galilée (1633)",c:"Condamné par l’Église pour avoir soutenu, preuves à l’appui, que la Terre tourne."},{t:"p",c:"**Commentaire.** Le conflit naît d’une **confusion des ordres** : l’autorité religieuse tranche une question de **fait** (astronomique) qui relève du **savoir**. La leçon n’est pas « religion contre science », mais qu’il faut distinguer les domaines : la science dit *comment* est le monde, la religion prétend dire un *sens*."}]},{h:"🌍 Prolongements — croire à l’âge de la science",blocks:[{t:"p",c:"La modernité a connu ce que Max Weber appelle le « **désenchantement du monde** » : la science explique par des causes ce qu’on attribuait au sacré. Pourtant la question religieuse ne disparaît pas ; elle se déplace. Les débats contemporains portent sur la **tolérance** (Voltaire) contre le **fanatisme**, sur la **laïcité**, sur le rapport entre convictions personnelles et espace public."},{t:"p",c:"Philosophiquement, l’essentiel reste de ne pas confondre les plans : on peut être croyant et rationnel (Pascal, Descartes), athée et respectueux, sans réduire la foi à de la crédulité ni la raison à de la froideur. Le véritable adversaire commun, c’est le **dogmatisme** — la pensée qui refuse d’être interrogée."},{t:"tip",h:"Ouverture",c:"Relier religion et vérité : la question « peut-on prouver Dieu ? » éclaire la distinction croire/savoir et les limites de la démonstration."}]},{h:"✍️ Deuxième dissertation guidée — « Croire, est-ce renoncer à la raison ? »",blocks:[{t:"list",c:["**I. Croire semble renoncer à la raison.** Adhérer sans preuve, c’est suspendre l’exigence de démonstration ; la foi peut sembler crédulité, voire fanatisme quand elle refuse tout examen.","**II. Mais croire n’est pas déraisonner.** Croire et savoir n’ont pas le même objet (Pascal) : la foi porte sur un sens, une espérance, non sur des faits mesurables. On peut croire **et** raisonner (théologie, Descartes).","**III. Dépassement.** Ce n’est pas la croyance qui s’oppose à la raison, mais la croyance **qui refuse de se penser** (le fanatisme). Une foi qui accepte le doute et le dialogue n’est pas un renoncement à la raison : elle en est une autre forme."]},{t:"example",h:"Conclusion",c:"Croire n’est renoncer à la raison que lorsque la croyance se fait dogme intouchable. Distinguées et humbles, foi et raison peuvent cohabiter dans un même esprit."}]}],"philo-technique":[{h:"🔎 Définitions & distinctions approfondies",blocks:[{t:"p",c:"La technique désigne l’ensemble des **procédés efficaces**, appris et transmissibles, par lesquels l’homme transforme la nature pour satisfaire ses besoins. Elle se distingue de la **science** (qui vise le vrai, la connaissance désintéressée) et de l’**art** (qui vise le beau). Longtemps, science et technique furent séparées ; la modernité les a nouées en une **technoscience** où la théorie sert l’application et l’application relance la théorie."},{t:"p",c:"La distinction décisive pour juger la technique est celle du **moyen** et de la **fin** : la technique est un **moyen**, neutre en soi ; sa valeur dépend de la **fin** poursuivie et de l’**usage**. Un même savoir (la chimie, le nucléaire, l’informatique) peut soigner ou détruire. S’ajoutent la distinction **outil / machine** (l’outil prolonge la main, la machine remplace le geste et rend l’homme surveillant) et la notion d’**aliénation** (être dépossédé du sens de son activité)."},{t:"table",head:["Distinction","Un côté","L’autre côté"],rows:[["Technique / science","Vise l’efficace, l’utile","Vise le vrai, la connaissance"],["Moyen / fin","La technique (neutre)","L’usage, le but (jugés)"],["Outil / machine","Prolonge le geste humain","Remplace le geste, l’automatise"],["Travail / aliénation","Se réaliser en produisant","Se perdre dans un travail vidé de sens"]]},{t:"tip",h:"À retenir",c:"L’homme est *homo faber* (Bergson) : la technique n’est pas un accessoire de l’humanité, elle en est **constitutive**."}]},{h:"⚔️ Les grandes thèses — la technique libère-t-elle ?",blocks:[{t:"p",c:"**Thèse 1 — la technique libère et humanise.** Elle affranchit des contraintes naturelles (Descartes), réduit la pénibilité, prolonge la vie. Chez **Hegel**, c’est par le **travail** que l’esclave, façonnant le monde, accède à la conscience de soi : transformer la nature, c’est se transformer soi-même."},{t:"p",c:"**Thèse 2 — la technique peut asservir.** **Marx** : le travail industriel **aliène** l’ouvrier, dépossédé du produit et du sens de son geste. **Heidegger** : la technique moderne réduit tout — la nature, l’homme — à un « **fonds** » (*Bestand*), une réserve disponible et calculable ; le fleuve n’est plus contemplé, il est « sommé » de fournir de l’énergie."},{t:"p",c:"**Thèse 3 — la technique appelle une éthique nouvelle.** **Jonas** : notre puissance est devenue si grande qu’elle engage l’existence de l’humanité future ; il faut un **principe responsabilité**. **Rousseau**, enfin, avertit : le progrès technique n’entraîne pas le progrès **moral** ; sciences et arts n’ont pas rendu les hommes meilleurs."},{t:"warning",h:"Piège",c:"Le **déterminisme technique** : croire que la technique évolue seule et nous impose ses effets. En réalité, ce sont des **choix** (politiques, économiques, éthiques) qui décident de ses usages."}]},{h:"📜 Textes & cas commentés",blocks:[{t:"example",h:"Bergson — homo faber",c:"« L’intelligence, envisagée dans ce qui en paraît être la démarche originelle, est la faculté de fabriquer des objets artificiels, en particulier des outils à faire des outils. » (*L’Évolution créatrice*)"},{t:"p",c:"**Commentaire.** Bergson définit l’homme moins par la pensée abstraite (*sapiens*) que par la **fabrication** (*faber*) : l’outil qui fait d’autres outils marque un saut décisif. La technique n’est pas extérieure à l’intelligence : elle en est l’expression première."},{t:"example",h:"Cas — le smartphone",c:"Il nous relie au monde entier… et nous soumet aux notifications, à la surveillance des données, à l’économie de l’attention."},{t:"p",c:"**Commentaire.** Une seule technique, deux visages : libération (accès au savoir, aux autres) et servitude (dépendance, captation du temps). Le cas illustre parfaitement que **tout dépend de l’usage** et de la maîtrise que nous en gardons — la question n’est jamais « pour ou contre », mais « comment »."}]},{h:"🌍 Prolongements — IA, bioéthique, écologie",blocks:[{t:"p",c:"La technique contemporaine pose des questions inédites. L’**intelligence artificielle** : une machine qui « décide » nous déresponsabilise-t-elle ? Peut-elle créer, penser ? La **bioéthique** : jusqu’où modifier le vivant, l’humain (génétique, procréation) ? L’**écologie** : la puissance technique, qui a permis de dominer la nature, menace aujourd’hui la biosphère."},{t:"p",c:"Toutes ces questions reconduisent les thèses classiques : la neutralité (moyen/fin), la maîtrise (Descartes), l’aliénation (Marx), l’arraisonnement du monde (Heidegger), la responsabilité (Jonas). La littérature l’avait anticipé : *Frankenstein* (la créature qui échappe au créateur), *Le Meilleur des mondes* (l’homme fabriqué et « heureux »)."},{t:"tip",h:"Ouverture",c:"Relier technique et liberté : la technique promet de nous libérer, mais peut créer de nouvelles dépendances ; la vraie liberté est de rester maître de nos moyens."}]},{h:"✍️ Deuxième dissertation guidée — « Le progrès technique rend-il l’homme meilleur ? »",blocks:[{t:"list",c:["**I. Le progrès technique améliore la condition humaine.** Santé, confort, savoirs, communication : la technique recule la souffrance et élargit nos possibles. Elle libère du temps pour la culture et la vie de l’esprit.","**II. Mais progrès technique ≠ progrès moral.** Rousseau en doute ; le XXᵉ siècle l’a prouvé tragiquement (la technique au service de la barbarie). Plus de pouvoir n’implique pas plus de sagesse ; la technique peut aliéner et déshumaniser (Marx, Heidegger).","**III. Dépassement.** La technique donne des **moyens** ; elle ne fixe pas les **fins**. Elle ne rend pas meilleur par elle-même : tout dépend de l’usage, qui relève de la morale et de la politique, non de la technique."]},{t:"example",h:"Conclusion",c:"Le progrès technique augmente notre puissance, non notre bonté. Il rend l’homme meilleur seulement si une conscience éthique en gouverne l’usage : le vrai progrès est d’abord celui de la responsabilité."}]}],"philo-verite":[{h:"🔎 Définitions & distinctions approfondies",blocks:[{t:"p",c:"La vérité se définit classiquement comme l’**accord de la pensée avec son objet** (théorie de l’adéquation). Il faut aussitôt la distinguer de la **réalité** : la réalité est ce qui **est** ; la vérité qualifie nos **jugements** sur le réel. Une chose n’est ni vraie ni fausse ; c’est ce que j’en **affirme** qui peut l’être. On distingue aussi la vérité de la **certitude** (état subjectif de conviction : on peut être certain et se tromper) et de la **vraisemblance** (ce qui a l’air vrai)."},{t:"p",c:"Deux distinctions structurent la notion. D’abord **opinion / savoir** : l’opinion (*doxa*) est une croyance non fondée, même partagée ; le savoir (*épistémè*) est justifié. Ensuite, avec **Leibniz**, **vérités de raison** (nécessaires, universelles, comme les mathématiques : leur contraire est impossible) et **vérités de fait** (contingentes, vérifiées par l’expérience : « César a franchi le Rubicon » — cela aurait pu ne pas être). On ne prouve pas les secondes comme les premières."},{t:"table",head:["Distinction","Un côté","L’autre côté"],rows:[["Vérité / réalité","Propriété du jugement","Ce qui est"],["Vérité / certitude","Accord avec l’objet","Conviction subjective (faillible)"],["Opinion / savoir","Croyance non fondée","Connaissance justifiée"],["Vérités de raison / de fait","Nécessaires (logique)","Contingentes (expérience)"]]},{t:"warning",h:"Relativisme",c:"« À chacun sa vérité » confond le **goût** (subjectif, légitime) et la **vérité** (qui prétend valoir pour tous). Sur un fait, toutes les opinions ne se valent pas."}]},{h:"⚔️ Les grandes thèses — comment atteindre le vrai ?",blocks:[{t:"p",c:"**Thèse 1 — par la conversion du regard (Platon).** L’allégorie de la caverne : enchaînés, nous prenons les **ombres** pour la réalité ; philosopher, c’est se retourner, sortir, contempler le soleil (l’Idée du Bien). La vérité se conquiert contre les apparences et l’opinion."},{t:"p",c:"**Thèse 2 — par le doute méthodique (Descartes).** Douter volontairement de tout — sens, raisonnements, monde — jusqu’à une première certitude que le doute ne peut emporter : « je pense, donc je suis ». La vérité se fonde sur l’évidence claire et distincte. **Thèse 3 — par l’expérience et la réfutation (empirisme, Popper).** Les vérités de fait se vérifient par l’expérience ; et une théorie n’est **scientifique** que si elle est **réfutable** (falsifiable) : ce qu’aucune expérience ne pourrait contredire n’est pas une science."},{t:"p",c:"**Thèse 4 — la vérité est conquise contre l’erreur (Bachelard).** La connaissance scientifique progresse en franchissant des « **obstacles épistémologiques** » : nos évidences premières, nos images spontanées sont d’abord des obstacles à dépasser. La vérité n’est jamais donnée, toujours construite et rectifiée."},{t:"tip",h:"À retenir",c:"Le **doute** cartésien n’est pas le scepticisme : c’est un **outil** pour atteindre le certain, non une fin en soi."}]},{h:"📜 Textes & cas commentés",blocks:[{t:"example",h:"Descartes — le cogito",c:"« Je pense, donc je suis. » (*Discours de la méthode*, IV)"},{t:"p",c:"**Commentaire.** Même en doutant de tout, une chose résiste : pour douter, il faut penser, et pour penser, il faut exister. Le cogito est la première **certitude indubitable**, le socle sur lequel Descartes va reconstruire le savoir. Le doute, poussé à l’extrême, se retourne en fondement."},{t:"example",h:"Cas — « la Terre est plate »",c:"Longtemps évidence partagée, aujourd’hui fausse : une croyance majoritaire n’est pas une vérité."},{t:"p",c:"**Commentaire.** Le cas montre que la vérité ne se **décide pas au vote** : elle se démontre ou se vérifie. Il montre aussi que la vérité scientifique est **révisable** — non par faiblesse, mais parce qu’une pensée qui se corrige est plus fiable qu’une pensée qui se croit définitive."}]},{h:"🌍 Prolongements — vérité, sciences et post-vérité",blocks:[{t:"p",c:"À l’ère des réseaux, la question de la vérité devient brûlante : « **fake news** », théories du complot, « **post-vérité** » où l’émotion l’emporte sur les faits. La distinction opinion/savoir n’a jamais été aussi nécessaire : la liberté d’exprimer une opinion n’implique pas que toutes les opinions se valent devant les faits."},{t:"p",c:"Du côté des sciences, la vérité se pense comme **provisoire et rectifiable** (Popper : une théorie tient tant qu’elle n’est pas réfutée) sans pour autant sombrer dans le relativisme : c’est justement parce qu’elle se soumet à l’épreuve que la science est fiable. **Orwell** (*1984*, le « Ministère de la Vérité ») rappelle l’enjeu politique : abolir l’idée d’une vérité indépendante, c’est le rêve de tout pouvoir totalitaire."},{t:"tip",h:"Ouverture",c:"Relier vérité et liberté : sans vérité partagée, plus de débat possible ; la démocratie suppose que l’on cherche ensemble le vrai."}]},{h:"✍️ Deuxième dissertation guidée — « Peut-on douter de tout ? »",blocks:[{t:"list",c:["**I. Oui, on peut douter de tout (doute radical).** Les sens trompent, les raisonnements peuvent errer, un « malin génie » pourrait me tromper (Descartes). Rien ne semble à l’abri du doute — c’est la force du scepticisme.","**II. Mais le doute rencontre une limite.** En doutant, je pense ; en pensant, j’existe : le cogito résiste au doute. Douter de tout absolument est impossible, car le doute lui-même suppose un sujet qui doute.","**III. Dépassement.** Le doute n’est fécond que s’il est **méthodique** (un outil pour trouver le certain), non **sceptique** (une fin qui paralyse). Douter de tout, ce n’est pas ne croire à rien : c’est se donner les moyens de savoir."]},{t:"example",h:"Conclusion",c:"On peut mettre tout en doute, sauf l’acte même de douter : le doute, loin de ruiner la vérité, en est le chemin, à condition de viser, au bout, une certitude."}]}],"philo-methode":[{h:"🧩 Le vocabulaire et les connecteurs de la dissertation",blocks:[{t:"p",c:"Une copie de philosophie se reconnaît à sa **langue**. Quelques réflexes de vocabulaire font gagner des points : « **problématiser** » (montrer la tension), « **une distinction** » (préciser deux sens d’un mot), « **un présupposé** » (ce que le sujet tient pour acquis), « **une objection** », « **une nuance** ». On évite « je pense que », « de nos jours », « depuis la nuit des temps », les généralités et le « bla-bla »."},{t:"table",head:["Pour…","Connecteurs à utiliser"],rows:[["Ajouter un argument","de plus, en outre, par ailleurs"],["Opposer (antithèse)","mais, cependant, toutefois, or"],["Conclure une étape","donc, ainsi, par conséquent"],["Nuancer","certes… mais, dans une certaine mesure"],["Illustrer","par exemple, ainsi, comme le montre"],["Dépasser","en réalité, plus profondément, il faut alors distinguer"]]},{t:"tip",h:"Structure d’un paragraphe",c:"Une **idée** (la phrase-clé) + un **argument** (pourquoi c’est vrai) + un **exemple ou un auteur** (qui l’illustre) + une **transition** vers la suite. Toujours dans cet ordre."}]},{h:"🎯 Trouver la problématique : la méthode pas à pas",blocks:[{t:"p",c:"Problématiser, c’est transformer un sujet en un **problème** : montrer que la réponse spontanée (« oui, évidemment » ou « non, bien sûr ») se heurte à une objection sérieuse. La technique : formuler la **réponse évidente**, puis l’**objection** qui la fragilise, et faire jaillir la **tension** entre les deux."},{t:"list",c:["**Repérer les mots** du sujet et leurs sens possibles (un mot = souvent plusieurs sens).","**Formuler la thèse spontanée** : ce que « tout le monde » répondrait.","**Chercher l’objection** : dans quel cas cette réponse est-elle fausse ou insuffisante ?","**Énoncer le problème** : « Faut-il donc… ou au contraire… ? » — c’est votre problématique."]},{t:"example",h:"Exemple",c:"Sujet : « Faut-il toujours dire la vérité ? » — Réponse spontanée : oui, mentir est mal. Objection : mais un mensonge peut protéger (le « mensonge charitable »). Problématique : la vérité est-elle un devoir **absolu**, ou doit-elle se plier à d’autres exigences (le bien d’autrui) ?"},{t:"tip",h:"Réflexe",c:"Une bonne problématique tient en **une question précise**, pas en une reformulation du sujet. Elle annonce déjà le plan."}]},{h:"🗂️ Banque de sujets par notion (avec problématiques)",blocks:[{t:"table",head:["Notion","Sujet possible","Tension à dégager"],rows:[["L’art","L’art n’a-t-il pour but que le beau ?","Plaire / dire une vérité, déranger"],["La justice","Est-il toujours juste d’obéir à la loi ?","Légal / légitime"],["La liberté","Être libre, est-ce faire ce que l’on veut ?","Licence / autonomie"],["La nature","L’homme doit-il dominer la nature ?","Maîtrise / responsabilité"],["La religion","La foi est-elle contraire à la raison ?","Croire / savoir"],["La technique","La technique nous libère-t-elle ?","Moyen / fin, libération / aliénation"],["La vérité","Toutes les opinions se valent-elles ?","Opinion / savoir"]]},{t:"tip",h:"Entraînement",c:"Pour chaque sujet, entraîne-toi à écrire **seulement l’introduction** (amener → définir → problématiser → annoncer). C’est l’exercice le plus rentable."}]},{h:"🚫 Les erreurs qui coûtent le plus au bac",blocks:[{t:"list",c:["**Le hors-sujet** : on répond à une autre question que celle posée. Remède : recopier le sujet en tête de brouillon et y revenir sans cesse.","**La récitation** : on déroule le cours sans problématiser. Remède : chaque paragraphe doit **répondre** au problème, pas exposer un savoir.","**La juxtaposition d’avis** : « certains pensent… d’autres pensent… ». Remède : un plan **progressif**, où chaque partie dépasse la précédente.","**Les exemples plaqués** : citer un auteur sans l’expliquer. Remède : montrer **ce que l’exemple apporte** à l’argument.","**La conclusion molle** (« ça dépend », « chacun voit »). Remède : **trancher** clairement le problème posé."]},{t:"warning",h:"À bannir",c:"Le « je pense que… » sans argument, les généralités (« de tout temps l’homme… »), et le mélange dissertation / explication de texte : lisez bien la consigne."}]}]},v=Object.freeze(Object.defineProperty({__proto__:null,default:p},Symbol.toStringTag,{value:"Module"}));export{h as a,d,m as e,b as m,v as p};
